export type StarterSource = 'cache' | 'live' | 'mixed' | 'snapshot'

export type SearchState =
  | { status: 'idle' }
  | { status: 'searching'; query: string }
  | { status: 'done'; query: string; found: number; added: number }
  | { status: 'error'; query: string; message: string }

export interface CollectionState {
  status: 'loading' | 'ready'
  byId: Record<number, Artwork>
  /** Every work: the starter collection, then works added by searches. */
  order: number[]
  /** The starter collection only; the default order for previous and next. */
  starterOrder: number[]
  source: StarterSource | null
  /** A non-blocking message about how the starter collection loaded. */
  notice: string | null
  /** Fixed for the session once the starter collection has loaded. */
  typeOptions: string[]
  search: SearchState
}

export type CollectionAction =
  | {
      type: 'starterLoaded'
      works: Artwork[]
      source: StarterSource
      notice: string | null
    }
  | { type: 'searchStarted'; query: string }
  | { type: 'searchSucceeded'; query: string; works: Artwork[] }
  | { type: 'searchFailed'; query: string; message: string }
  | { type: 'searchCleared' }

export const initialState: CollectionState = {
  status: 'loading',
  byId: {},
  order: [],
  starterOrder: [],
  source: null,
  notice: null,
  typeOptions: [],
  search: { status: 'idle' },
}

function typesOf(works: Artwork[]): string[] {
  const types = new Set(works.flatMap((work) => work.artworkType ?? []))
  return [...types].sort((a, b) => a.localeCompare(b))
}

export function collectionReducer(
  state: CollectionState,
  action: CollectionAction,
): CollectionState {
  switch (action.type) {
    case 'starterLoaded': {
      const order = action.works.map((work) => work.id)
      return {
        ...state,
        status: 'ready',
        byId: Object.fromEntries(action.works.map((work) => [work.id, work])),
        order,
        starterOrder: order,
        source: action.source,
        notice: action.notice,
        typeOptions: typesOf(action.works),
      }
    }
    case 'searchStarted':
      return { ...state, search: { status: 'searching', query: action.query } }
    case 'searchSucceeded': {
      const fresh = action.works.filter((work) => !(work.id in state.byId))
      const byId = { ...state.byId }
      for (const work of fresh) byId[work.id] = work
      return {
        ...state,
        byId,
        order: [...state.order, ...fresh.map((work) => work.id)],
        search: {
          status: 'done',
          query: action.query,
          found: action.works.length,
          added: fresh.length,
        },
      }
    }
    case 'searchFailed':
      return {
        ...state,
        search: { status: 'error', query: action.query, message: action.message },
      }
    case 'searchCleared':
      return { ...state, search: { status: 'idle' } }
  }
}

export function allWorks(state: CollectionState): Artwork[] {
  return state.order.map((id) => state.byId[id])
}

export function starterWorks(state: CollectionState): Artwork[] {
  return state.starterOrder.map((id) => state.byId[id])
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\collection\loadStarter.ts", "content": "import type { Artwork } from '../types/artwork'
import { readCache, writeCache } from './cache'
import type { StarterSource } from './collectionReducer'

export interface StarterResult {
  works: Artwork[]
  source: StarterSource
  notice: string | null
}

interface Options {
  loadDepartment: (department: string) => Promise<Artwork[]>
  loadSnapshot: () => Promise<Artwork[]>
  departments: string[]
  now: number
}

function unique(works: Artwork[]): Artwork[] {
  const seen = new Set<number>()
  return works.filter((work) => !seen.has(work.id) && seen.add(work.id))
}

/**
 * The starter collection: from the cache when fresh, otherwise one request per
 * department. A department that fails or comes back empty is filled from the
 * bundled snapshot, and only a fully live load is cached.
 */
export async function loadStarter({
  loadDepartment,
  loadSnapshot,
  departments,
  now,
}: Options): Promise<StarterResult> {
  const cached = readCache(now)
  if (cached) return { works: cached, source: 'cache', notice: null }

  const settled = await Promise.allSettled(departments.map(loadDepartment))
  const rooms = settled.map((result) =>
    result.status === 'fulfilled' ? result.value : [],
  )
  const missing = departments.filter((_, index) => rooms[index].length === 0)

  if (missing.length === 0) {
    const works = unique(rooms.flat())
    writeCache(works, now)
    return { works, source: 'live', notice: null }
  }

  const snapshot = await loadSnapshot()
  const filled = rooms.map((room, index) =>
    room.length > 0
      ? room
      : snapshot.filter((work) => work.department === departments[index]),
  )
  const works = unique(filled.flat())

  if (missing.length === departments.length) {
    return {
      works,
      source: 'snapshot',
      notice:
        'The Art Institute API could not be reached, so this is a saved copy of the collection.',
    }
  }
  return {
    works,
    source: 'mixed',
    notice: `Some rooms are showing a saved copy because they could not be loaded: ${missing.join(', ')}.`,
  }
}
"}

