Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\components\ArtworkImage.tsx", "content": "import { useState } from 'react'
import { imageUrl } from '../api/artic'
import styles from './ArtworkImage.module.css'

interface Props {
  imageId: string
  title: string | null
  size: 'thumb' | 'full'
  /** How the image fills its box: cropped to fill, or shown whole. */
  fit?: 'cover' | 'contain'
  /** Load at once instead of when scrolled into view. */
  eager?: boolean
}

export function ArtworkImage({
  imageId,
  title,
  size,
  fit = 'cover',
  eager = false,
}: Props) {
  const [failedId, setFailedId] = useState<string | null>(null)
  const alt = title ?? 'Untitled artwork'

  if (failedId === imageId) {
    return (
      <span className={styles.placeholder} role="img" aria-label={alt}>
        Image unavailable
      </span>
    )
  }

  return (
    <img
      className={`${styles.image} ${styles[fit]}`}
      src={imageUrl(imageId, size)}
      alt={alt}
      loading={eager ? 'eager' : 'lazy'}
      decoding="async"
      onError={() => setFailedId(imageId)}
    />
  )
}
"}

