  border: 1px solid var(--accent);
  border-radius: var(--radius);
  background: transparent;
  color: var(--accent);
  font-weight: 600;
  overflow-wrap: anywhere;
}

.museumButton:hover:not(:disabled) {
  background: var(--accent);
  color: var(--on-accent);
}

.museumButton:disabled {
  opacity: 0.6;
  cursor: progress;
}

.rows {
  border-top: 1px solid var(--line);
}

.row {
  display: grid;
  grid-template-columns: 4rem minmax(0, 2fr) minmax(0, 1.4fr) 5.5rem;
  align-items: center;
  gap: var(--space-4);
  padding: var(--space-2) var(--space-2);
  border-bottom: 1px solid var(--line);
  color: var(--ink);
  text-decoration: none;
}

.row:hover {
  background: var(--paper);
  color: var(--ink);
}

.thumb {
  width: 4rem;
  height: 4rem;
  border: 3px solid var(--frame);
}

.title {
  font-family: var(--serif);
  font-size: var(--text-lg);
  line-height: 1.2;
  overflow-wrap: anywhere;
}

.row:hover .title {
  color: var(--accent);
}

.artist {
  color: var(--muted);
  overflow-wrap: anywhere;
}

.year {
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--muted);
}

@media (max-width: 40rem) {
  .row {
    grid-template-columns: 3.5rem minmax(0, 1fr) auto;
    grid-template-areas:
      'thumb title year'
      'thumb artist artist';
    gap: 0 var(--space-3);
  }

  .thumb {
    grid-area: thumb;
    width: 3.5rem;
    height: 3.5rem;
  }

  .title {
    grid-area: title;
    font-size: var(--text-md);
  }

  .artist {
    grid-area: artist;
    font-size: var(--text-sm);
  }

  .year {
    grid-area: year;
    font-size: var(--text-sm);
  }

  .direction,
  .field {
    flex: 1 1 auto;
  }
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\components\FilterChips.tsx", "content": "import styles from './FilterChips.module.css'

interface Props {
  legend: string
  options: string[]
  selected: string[]
  onToggle: (option: string) => void
}

export function FilterChips({ legend, options, selected, onToggle }: Props) {
  return (
    <fieldset className={styles.group}>
      <legend className={styles.legend}>{legend}</legend>
      <ul className={styles.chips}>
        {options.map((option) => {
          const on = selected.includes(option)
          return (
            <li key={option}>
              <button
                type="button"
                className={on ? `${styles.chip} ${styles.on}` : styles.chip}
                aria-pressed={on}
                onClick={() => onToggle(option)}
              >
                {option}
              </button>
            </li>
          )
        })}
      </ul>
    </fieldset>
  )
}
"}

