Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\test\renderApp.tsx", "content": "import { render } from '@testing-library/react'
import { MemoryRouter, useLocation } from 'react-router-dom'
import { vi } from 'vitest'
import App from '../App'
import { CollectionProvider } from '../collection/CollectionProvider'
import type { Artwork } from '../types/artwork'

export const TEST_DEPARTMENTS = ['Arts of Asia', 'Textiles', 'Modern Art']

interface Options {
  works: Artwork[]
  /** What a full-museum search returns, or an error to reject with. */
  museum?: Artwork[] | Error
  /** Works that exist in the museum but not in the starter collection. */
  elsewhere?: Artwork[]
  fetchError?: Error
}

function Address() {
  const location = useLocation()
  return <p data-testid="address">{location.pathname + location.search}</p>
}

/** The whole app at a route, backed by a fake API holding the given works. */
export function renderApp(route: string, options: Options) {
  const { works, museum = [], elsewhere = [], fetchError } = options
  const client = {
    loadDepartment: vi.fn(async (department: string) =>
      works.filter((work) => work.department === department),
    ),
    searchMuseum: vi.fn(async () => {
      if (museum instanceof Error) throw museum
      return museum
    }),
    fetchArtwork: vi.fn(async (id: number) => {
      if (fetchError) throw fetchError
      return [...works, ...elsewhere].find((work) => work.id === id) ?? null
    }),
  }

  const view = render(
    <MemoryRouter initialEntries={[route]}>
      <CollectionProvider
        client={client}
        departments={TEST_DEPARTMENTS}
        loadSnapshot={async () => []}
      >
        <App />
        <Address />
      </CollectionProvider>
    </MemoryRouter>,
  )
  return { ...view, client }
}
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\App.test.tsx", "content": "import { fireEvent, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { work } from './test/fixtures'
import { renderApp } from './test/renderApp'

const works = [
  work({ id: 27992, title: 'A Sunday on La Grande Jatte', department: 'Arts of Asia' }),
  work({ id: 2, department: 'Textiles' }),
]

describe('routes', () => {
  it('shows the List at the root', async () => {
    renderApp('/', { works })
    expect(await screen.findByRole('heading', { level: 1, name: 'The collection' })).toBeVisible()
    expect(screen.getByRole('link', { name: 'List' })).toHaveAttribute('aria-current', 'page')
  })

  it('shows the Rooms view and marks its link current', async () => {
    renderApp('/rooms', { works })
    expect(await screen.findByRole('heading', { level: 1, name: 'The rooms' })).toBeVisible()
    expect(screen.getByRole('link', { name: 'Rooms' })).toHaveAttribute('aria-current', 'page')
    expect(screen.getByRole('link', { name: 'List' })).not.toHaveAttribute('aria-current')
  })

  it('shows the Timeline view', async () => {
    renderApp('/timeline', { works })
    expect(await screen.findByRole('heading', { level: 1, name: 'The timeline' })).toBeVisible()
  })

  it('shows the Detail view for an artwork address', async () => {
    renderApp('/artwork/27992', { works })
    expect(
      await screen.findByRole('heading', { level: 1, name: 'A Sunday on La Grande Jatte' }),
    ).toBeVisible()
  })

  it('shows Not found with a link to the List for an unknown address', async () => {
    renderApp('/nowhere', { works })
    expect(
      await screen.findByRole('heading', { level: 1, name: 'This room does not exist' }),
    ).toBeVisible()
    expect(screen.getByRole('link', { name: 'Go to the list of artworks' })).toHaveAttribute(
      'href',
      '/',
    )
  })
})

describe('artwork images', () => {
  it('use the title as alt text', async () => {
    renderApp('/', { works })
    const image = await screen.findByRole('img', { name: 'A Sunday on La Grande Jatte' })
    expect(image).toHaveAttribute('loading', 'lazy')
    expect(image.getAttribute('src')).toContain('/full/200,/0/default.jpg')
  })

  it('fall back to "Untitled artwork" when there is no title', async () => {
    renderApp('/', { works: [work({ id: 5, title: null, department: 'Textiles' })] })
    expect(await screen.findByRole('img', { name: 'Untitled artwork' })).toBeVisible()
  })

  it('show a placeholder when the image fails to load', async () => {
    renderApp('/', { works })
    const image = await screen.findByRole('img', { name: 'A Sunday on La Grande Jatte' })
    fireEvent.error(image)
    const placeholder = await screen.findByRole('img', { name: 'A Sunday on La Grande Jatte' })
    expect(placeholder).toHaveTextContent('Image unavailable')
  })
})
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\views\ListView.test.tsx", "content": "import { screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it } from 'vitest'
import { ApiError } from '../api/artic'
import { loadTrail } from '../browse/trail'
import { work } from '../test/fixtures'
import { renderApp } from '../test/renderApp'

const works = [
  work({ id: 1, title: 'Paris Street; Rainy Day', artist: 'Gustave Caillebotte', year: 1877, department: 'Arts of Asia' }),
  work({ id: 2, title: 'Water Lilies', artist: 'Claude Monet', year: 1906, department: 'Arts of Asia' }),
  work({ id: 3, title: 'Rain Forest Study', artist: null, year: 1850, department: 'Textiles' }),
  work({ id: 4, title: 'American Gothic', artist: 'Grant Wood', year: 1930, department: 'Modern Art' }),
]

async function rowTitles() {
  const list = await screen.findByRole('list', { name: '' }).catch(() => null)
  void list
  return screen
    .getAllByRole('link')
    .filter((link) => link.getAttribute('href')?.startsWith('/artwork/'))
    .map((link) => link.getAttribute('href'))
}

async function ready() {
  await screen.findByText(/^\d+ artworks?/)
}

describe('ListView', () => {
  it('shows every artwork sorted by title', async () => {
    renderApp('/', { works })
    await ready()
    expect(await rowTitles()).toEqual(['/artwork/4', '/artwork/1', '/artwork/3', '/artwork/2'])
    expect(screen.getByText('4 artworks')).toBeVisible()
  })

  it('filters as the visitor types', async () => {
    const user = userEvent.setup()
    renderApp('/', { works })
    await ready()
    await user.type(screen.getByRole('searchbox', { name: 'Search' }), 'rain')
    expect(await rowTitles()).toEqual(['/artwork/1', '/artwork/3'])
    expect(screen.getByText('2 artworks matching “rain”')).toBeVisible()
    expect(screen.getByTestId('address')).toHaveTextContent('/?q=rain')
  })

  it('sorts by year, latest first', async () => {
    const user = userEvent.setup()
    renderApp('/', { works })
    await ready()
    await user.selectOptions(screen.getByRole('combobox', { name: 'Sort by' }), 'year')
    await user.click(screen.getByRole('button', { name: 'Descending' }))
    expect(await rowTitles()).toEqual(['/artwork/4', '/artwork/2', '/artwork/1', '/artwork/3'])
    expect(screen.getByRole('button', { name: 'Descending' })).toHaveAttribute('aria-pressed', 'true')
    expect(screen.getByTestId('address')).toHaveTextContent('/?sort=year&dir=desc')
  })

  it('keeps the sort while searching (AE1)', async () => {
    const user = userEvent.setup()
    renderApp('/?sort=year&dir=desc', { works })
    await ready()
    await user.type(screen.getByRole('searchbox', { name: 'Search' }), 'rain')
    expect(await rowTitles()).toEqual(['/artwork/1', '/artwork/3'])
  })

  it('shows the state held in the address', async () => {
    renderApp('/?q=rain&sort=year&dir=asc', { works })
    await ready()
    expect(screen.getByRole('searchbox', { name: 'Search' })).toHaveValue('rain')
    expect(screen.getByRole('combobox', { name: 'Sort by' })).toHaveValue('year')
    expect(await rowTitles()).toEqual(['/artwork/3', '/artwork/1'])
  })

  it('shows "Unknown" for a missing artist', async () => {
    renderApp('/?q=forest', { works })
    await ready()
    const row = screen.getByRole('link', { name: /Rain Forest Study/ })
    expect(within(row).getByText('Unknown')).toBeVisible()
  })

  it('opens an artwork and saves the visible order as the trail', async () => {
    const user = userEvent.setup()
    renderApp('/?q=rain&sort=year', { works })
    await ready()
    await user.click(screen.getByRole('link', { name: /Paris Street/ }))
    expect(screen.getByTestId('address')).toHaveTextContent('/artwork/1')
    expect(loadTrail()?.entries.map((entry) => entry.id)).toEqual([3, 1])
    expect(loadTrail()?.returnTo).toBe('/?q=rain&sort=year')
  })

  it('shows an empty message and the full-museum button when nothing matches', async () => {
    renderApp('/?q=zzzz', { works })
    await ready()
    expect(screen.getByText('No artworks in the collection match “zzzz”.')).toBeVisible()
    expect(screen.getByRole('button', { name: 'Search the full museum for “zzzz”' })).toBeVisible()
  })

  it('hides the full-museum button when the search box is empty', async () => {
    renderApp('/', { works })
    await ready()
    expect(screen.queryByRole('button', { name: /Search the full museum/ })).toBeNull()
  })

  it('adds full-museum matches to the rows', async () => {
    const user = userEvent.setup()
    const museum = [
      work({ id: 2, title: 'Water Lilies', artist: 'Claude Monet' }),
      work({ id: 50, title: 'Stacks of Wheat', artist: 'Claude Monet', department: 'Modern Art' }),
    ]
    const { client } = renderApp('/?q=monet', { works, museum })
    await ready()
    await user.click(screen.getByRole('button', { name: /Search the full museum/ }))
    expect(await screen.findByRole('link', { name: /Stacks of Wheat/ })).toBeVisible()
    expect(client.searchMuseum).toHaveBeenCalledWith('monet')
    expect(
      screen.getByText('The full museum returned 2 of its best matches; 1 were new and have been added.'),
    ).toBeVisible()
    expect(await rowTitles()).toEqual(['/artwork/50', '/artwork/2'])
  })

  it('shows an error and keeps the rows when the full-museum search fails (AE5)', async () => {
    const user = userEvent.setup()
    renderApp('/?q=rain', { works, museum: new ApiError('Could not reach the Art Institute API.') })
    await ready()
    await user.click(screen.getByRole('button', { name: /Search the full museum/ }))
    expect(await screen.findByRole('alert')).toHaveTextContent(
      'Could not reach the Art Institute API. The artworks below are unchanged.',
    )
    expect(await rowTitles()).toEqual(['/artwork/1', '/artwork/3'])
  })
})
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\views\RoomsView.test.tsx", "content": "import { screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it } from 'vitest'
import { loadTrail } from '../browse/trail'
import { work } from '../test/fixtures'
import { renderApp } from '../test/renderApp'

const works = [
  work({ id: 1, title: 'Scroll', department: 'Arts of Asia', artworkType: 'Painting' }),
  work({ id: 2, title: 'Buddha', department: 'Arts of Asia', artworkType: 'Sculpture' }),
  work({ id: 3, title: 'Woodblock', department: 'Arts of Asia', artworkType: 'Print' }),
  work({ id: 4, title: 'Tapestry', department: 'Textiles', artworkType: 'Textile' }),
  work({ id: 5, title: 'Cannons', department: 'Modern Art', artworkType: 'Painting' }),
]

function room(name: string) {
  return screen.getByRole('region', { name })
}

function worksIn(name: string) {
  return within(room(name))
    .queryAllByRole('link')
    .map((link) => link.getAttribute('href'))
}

async function ready() {
  await screen.findByText(/artworks in \d+ rooms|match(es)? your filters/)
}

describe('RoomsView', () => {
  it('renders a room for every department with works', async () => {
    renderApp('/rooms', { works })
    await ready()
    expect(worksIn('Arts of Asia')).toEqual(['/artwork/1', '/artwork/2', '/artwork/3'])
    expect(worksIn('Textiles')).toEqual(['/artwork/4'])
    expect(worksIn('Modern Art')).toEqual(['/artwork/5'])
    expect(screen.getByText('5 artworks in 3 rooms')).toBeVisible()
  })

  it('offers the artwork types found in the starter collection', async () => {
    renderApp('/rooms', { works })
    await ready()
    const group = screen.getByRole('group', { name: 'Type of artwork' })
    expect(within(group).getAllByRole('button').map((b) => b.textContent)).toEqual([
      'Painting',
      'Print',
      'Sculpture',
      'Textile',
    ])
  })

  it('shows works of either type when two types are selected', async () => {
    const user = userEvent.setup()
    renderApp('/rooms', { works })
    await ready()
    await user.click(screen.getByRole('button', { name: 'Painting' }))
    await user.click(screen.getByRole('button', { name: 'Print' }))
    expect(worksIn('Arts of Asia')).toEqual(['/artwork/1', '/artwork/3'])
    expect(worksIn('Modern Art')).toEqual(['/artwork/5'])
    expect(screen.getByRole('button', { name: 'Painting' })).toHaveAttribute('aria-pressed', 'true')
    expect(screen.getByTestId('address')).toHaveTextContent('/rooms?type=Painting&type=Print')
    expect(screen.getByText('3 artworks match your filters')).toBeVisible()
  })

  it('dims a room with no matching works and shows none of its artworks (AE2)', async () => {
    renderApp('/rooms?type=Painting&dept=Arts+of+Asia', { works })
    await ready()
    expect(worksIn('Arts of Asia')).toEqual(['/artwork/1'])
    expect(worksIn('Textiles')).toEqual([])
    expect(room('Textiles').className).toContain('dimmed')
    expect(within(room('Textiles')).getByText('Nothing here matches your filters')).toBeVisible()
    expect(room('Arts of Asia').className).not.toContain('dimmed')
  })

  it('restores every room when the filters are cleared', async () => {
    const user = userEvent.setup()
    renderApp('/rooms?type=Textile', { works })
    await ready()
    expect(worksIn('Arts of Asia')).toEqual([])
    await user.click(screen.getByRole('button', { name: 'Clear filters' }))
    expect(worksIn('Arts of Asia')).toHaveLength(3)
    expect(screen.queryByRole('button', { name: 'Clear filters' })).toBeNull()
    expect(screen.getByTestId('address')).toHaveTextContent('/rooms')
  })

  it('opens an artwork and saves that room’s visible works as the trail', async () => {
    const user = userEvent.setup()
    renderApp('/rooms?type=Painting&type=Print', { works })
    await ready()
    await user.click(within(room('Arts of Asia')).getByRole('link', { name: 'Woodblock' }))
    expect(screen.getByTestId('address')).toHaveTextContent('/artwork/3')
    expect(loadTrail()?.entries.map((entry) => entry.id)).toEqual([1, 3])
    expect(loadTrail()?.returnTo).toBe('/rooms?type=Painting&type=Print')
  })

  it('puts works added by a full-museum search in their department’s room', async () => {
    const user = userEvent.setup()
    const museum = [work({ id: 50, title: 'Haystack', department: 'Modern Art', artworkType: 'Mask' })]
    renderApp('/?q=hay', { works, museum })
    await user.click(await screen.findByRole('button', { name: /Search the full museum/ }))
    await screen.findByRole('link', { name: /Haystack/ })
    await user.click(screen.getByRole('link', { name: 'Rooms' }))
    await ready()
    expect(worksIn('Modern Art')).toEqual(['/artwork/5', '/artwork/50'])
    expect(screen.queryByRole('button', { name: 'Mask' })).toBeNull()
  })
})
"}

Write {"file_path": "C:\Users\User\Dropbox\UIUC\2026 Fall\CS 409 Art of Web Programming\mp2\src\views\TimelineView.test.tsx", "content": "import { screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { describe, expect, it } from 'vitest'
import { loadTrail } from '../browse/trail'
import { work } from '../test/fixtures'
import { renderApp } from '../test/renderApp'

const works = [
  work({ id: 1, title: 'Modern', year: 1930, department: 'Arts of Asia' }),
  work({ id: 2, title: 'Baroque', year: 1642, department: 'Arts of Asia' }),
  work({ id: 3, title: 'Impression', year: 1877, department: 'Textiles' }),
  work({ id: 4, title: 'Undated', year: null, department: 'Textiles' }),
  work({ id: 5, title: 'Ancient', year: -600, department: 'Modern Art' }),
]

function worksIn(period: string) {
  return within(screen.getByRole('region', { name: period }))
    .queryAllByRole('link')
    .map((link) => link.getAttribute('href'))
}

async function ready() {
  await screen.findByText(/dated artworks/)
}

describe('TimelineView', () => {
  it('puts works in different period columns in date order', async () => {
    renderApp('/timeline', { works })
    await ready()
    expect(worksIn('1600–1699')).toEqual(['/artwork/2'])
    expect(worksIn('1875–1899')).toEqual(['/artwork/3'])
    expect(worksIn('1925 and later')).toEqual(['/artwork/1'])
    const periods = screen.getAllByRole('heading', { level: 2 }).map((h) => h.textContent)
    expect(periods.indexOf('1600–1699')).toBeLessThan(periods.indexOf('1875–1899'))
    expect(periods.indexOf('1875–1899')).toBeLessThan(periods.indexOf('1925 and later'))
  })

  it('leaves out a work with no year and says how many are missing (AE4)', async () => {
    renderApp('/timeline', { works })
    await ready()
    expect(screen.queryByRole('link', { name: 'Undated' })).toBeNull()
    expect(screen.getByText(/1 artwork has no date and is not shown here/)).toBeVisible()
    expect(screen.getByText(/4 dated artworks/)).toBeVisible()
  })

  it('puts a work from before the first boundary in the first column', async () => {
    renderApp('/timeline', { works })
    await ready()
    expect(worksIn('Before the common era')).toEqual(['/artwork/5'])
  })

  it('opens an artwork and saves a trail ordered by year', async () => {
    const user = userEvent.setup()
    renderApp('/timeline', { works })
    await ready()
    await user.click(screen.getByRole('link', { name: 'Impression' }))
    expect(screen.getByTestId('address')).toHaveTextContent('/artwork/3')
    expect(loadTrail()?.entries.map((entry) => entry.id)).toEqual([5, 2, 3, 1])
    expect(loadTrail()?.returnTo).toBe('/timeline')
  })
})
