2043	+
2044	+/**
2045	+ * The starter collection: from the cache when fresh, otherwise one request per
2046	+ * department. A department that fails or comes back empty is filled from the
2047	+ * bundled snapshot, and only a fully live load is cached.
2048	+ */
2049	+export async function loadStarter({
2050	+  loadDepartment,
2051	+  loadSnapshot,
2052	+  departments,
2053	+  now,
2054	+}: Options): Promise<StarterResult> {
2055	+  const cached = readCache(now)
2056	+  if (cached) return { works: cached, source: 'cache', notice: null }
2057	+
2058	+  const settled = await Promise.allSettled(departments.map(loadDepartment))
2059	+  const rooms = settled.map((result) =>
2060	+    result.status === 'fulfilled' ? result.value : [],
2061	+  )
2062	+  const missing = departments.filter((_, index) => rooms[index].length === 0)
2063	+
2064	+  if (missing.length === 0) {
2065	+    const works = unique(rooms.flat())
2066	+    writeCache(works, now)
2067	+    return { works, source: 'live', notice: null }
2068	+  }
2069	+
2070	+  const snapshot = await loadSnapshot()
2071	+  const filled = rooms.map((room, index) =>
2072	+    room.length > 0
2073	+      ? room
2074	+      : snapshot.filter((work) => work.department === departments[index]),
2075	+  )
2076	+  const works = unique(filled.flat())
2077	+
2078	+  if (missing.length === departments.length) {
2079	+    return {
2080	+      works,
2081	+      source: 'snapshot',
2082	+      notice:
2083	+        'The Art Institute API could not be reached, so this is a saved copy of the collection.',
2084	+    }
2085	+  }
2086	+  return {
2087	+    works,
2088	+    source: 'mixed',
2089	+    notice: `Some rooms are showing a saved copy because they could not be loaded: ${missing.join(', ')}.`,
2090	+  }
2091	+}
