1	import type { Artwork } from '../types/artwork'
2	
3	/** Enough of an artwork to draw a filmstrip thumbnail and link to it. */
4	export interface TrailEntry {
5	  id: number
6	  title: string | null
7	  imageId: string
8	}
9	
10	/** The ordered works a visitor was browsing, and where to send them back. */
11	export interface Trail {
12	  entries: TrailEntry[]
13	  returnTo: string
14	}
15	
16	export interface Navigation {
17	  previous: TrailEntry
18	  next: TrailEntry
19	  /** The current work with its neighbours, in trail order. */
20	  strip: TrailEntry[]
21	  /** 1-based place in the trail, or null when the work is not in it. */
22	  position: number | null
23	  total: number
24	  inTrail: boolean
25	}
26	
27	const STORAGE_KEY = 'mp2.trail.v1'
28	const REACH = 2
29	
30	export function toEntry(work: Artwork): TrailEntry {
31	  return { id: work.id, title: work.title, imageId: work.imageId }
32	}
33	
34	export function makeTrail(works: Artwork[], returnTo: string): Trail {
35	  return { entries: works.map(toEntry), returnTo }
36	}
37	
38	export function navigate(trail: Trail, current: TrailEntry): Navigation {
39	  const { entries } = trail
40	  const total = entries.length
41	  const index = entries.findIndex((entry) => entry.id === current.id)
42	
43	  if (index === -1) {
44	    // Outside the trail: treated as sitting just before the first work.
45	    if (total === 0) {
46	      return {
47	        previous: current,
48	        next: current,
49	        strip: [current],
50	        position: null,
51	        total,
52	        inTrail: false,
53	      }
54	    }
55	    const first = entries[0]
56	    const last = entries[total - 1]
57	    return {
58	      previous: last,
59	      next: first,
60	      strip: total === 1 ? [current, first] : [last, current, first],
61	      position: null,
62	      total,
63	      inTrail: false,
64	    }
65	  }
66	
67	  const wrap = (offset: number) => entries[(index + offset + total) % total]
68	  const strip =
69	    total < REACH * 2 + 1
70	      ? entries
71	      : Array.from({ length: REACH * 2 + 1 }, (_, i) => wrap(i - REACH))
72	
73	  return {
74	    previous: wrap(-1),
75	    next: wrap(1),
76	    strip,
77	    position: index + 1,
78	    total,
79	    inTrail: true,
80	  }
81	}
82	
83	function isTrail(value: unknown): value is Trail {
84	  if (typeof value !== 'object' || value === null) return false
85	  const candidate = value as Partial<Trail>
86	  return (
87	    typeof candidate.returnTo === 'string' &&
88	    Array.isArray(candidate.entries) &&
89	    candidate.entries.every(
90	      (entry) =>
91	        typeof entry?.id === 'number' && typeof entry?.imageId === 'string',
92	    )
93	  )
94	}
95	
96	// Kept in memory as well, so the trail still works when storage is blocked.
97	let current: Trail | null = null
98	
99	export function saveTrail(trail: Trail): void {
100	  current = trail
101	  try {
102	    window.sessionStorage.setItem(STORAGE_KEY, JSON.stringify(trail))
103	  } catch {
104	    // Storage full or blocked: previous and next fall back to default order.
105	  }
106	}
107	
108	export function clearTrail(): void {
109	  current = null
110	  try {
111	    window.sessionStorage.removeItem(STORAGE_KEY)
112	  } catch {
113	    // Nothing to clear.
114	  }
115	}
116	
117	export function loadTrail(): Trail | null {
118	  if (current) return current
119	  try {
120	    const saved = window.sessionStorage.getItem(STORAGE_KEY)
121	    if (!saved) return null
122	    const parsed: unknown = JSON.parse(saved)
123	    return isTrail(parsed) ? parsed : null
124	  } catch {
125	    return null
126	  }
127	}
