1	import type { Artwork } from '../types/artwork'
2	
3	export type StarterSource = 'cache' | 'live' | 'mixed' | 'snapshot'
4	
5	export type SearchState =
6	  | { status: 'idle' }
7	  | { status: 'searching'; query: string }
8	  | { status: 'done'; query: string; found: number; added: number; ids: number[] }
9	  | { status: 'error'; query: string; message: string }
10	
11	export interface CollectionState {
12	  status: 'loading' | 'ready'
13	  byId: Record<number, Artwork>
14	  /** Every work: the starter collection, then works added by searches. */
15	  order: number[]
16	  /** The starter collection only; the default order for previous and next. */
17	  starterOrder: number[]
18	  source: StarterSource | null
19	  /** A non-blocking message about how the starter collection loaded. */
20	  notice: string | null
21	  /** Fixed for the session once the starter collection has loaded. */
22	  typeOptions: string[]
23	  search: SearchState
24	}
25	
26	export type CollectionAction =
27	  | {
28	      type: 'starterLoaded'
29	      works: Artwork[]
30	      source: StarterSource
31	      notice: string | null
32	    }
33	  | { type: 'searchStarted'; query: string }
34	  | { type: 'searchSucceeded'; query: string; works: Artwork[] }
35	  | { type: 'searchFailed'; query: string; message: string }
36	  | { type: 'searchCleared' }
37	
38	export const initialState: CollectionState = {
39	  status: 'loading',
40	  byId: {},
41	  order: [],
42	  starterOrder: [],
43	  source: null,
44	  notice: null,
45	  typeOptions: [],
46	  search: { status: 'idle' },
47	}
48	
49	function typesOf(works: Artwork[]): string[] {
50	  const types = new Set(works.flatMap((work) => work.artworkType ?? []))
51	  return [...types].sort((a, b) => a.localeCompare(b))
52	}
53	
54	export function collectionReducer(
55	  state: CollectionState,
56	  action: CollectionAction,
57	): CollectionState {
58	  switch (action.type) {
59	    case 'starterLoaded': {
60	      const order = action.works.map((work) => work.id)
61	      return {
62	        ...state,
63	        status: 'ready',
64	        byId: Object.fromEntries(action.works.map((work) => [work.id, work])),
65	        order,
66	        starterOrder: order,
67	        source: action.source,
68	        notice: action.notice,
69	        typeOptions: typesOf(action.works),
70	      }
71	    }
72	    case 'searchStarted':
73	      return { ...state, search: { status: 'searching', query: action.query } }
74	    case 'searchSucceeded': {
75	      const fresh = action.works.filter((work) => !(work.id in state.byId))
76	      const byId = { ...state.byId }
77	      for (const work of fresh) byId[work.id] = work
78	      return {
79	        ...state,
80	        byId,
81	        order: [...state.order, ...fresh.map((work) => work.id)],
82	        search: {
83	          status: 'done',
84	          query: action.query,
85	          found: action.works.length,
86	          added: fresh.length,
87	          ids: action.works.map((work) => work.id),
88	        },
89	      }
90	    }
91	    case 'searchFailed':
92	      return {
93	        ...state,
94	        search: { status: 'error', query: action.query, message: action.message },
95	      }
96	    case 'searchCleared':
97	      return { ...state, search: { status: 'idle' } }
98	  }
99	}
100	
101	export function allWorks(state: CollectionState): Artwork[] {
102	  return state.order.map((id) => state.byId[id])
103	}
104	
105	export function starterWorks(state: CollectionState): Artwork[] {
106	  return state.starterOrder.map((id) => state.byId[id])
107	}
