1	import type { Artwork } from '../types/artwork'
2	
3	/** Change the version when the shape of a cached artwork changes. */
4	export const CACHE_KEY = 'mp2.collection.v1'
5	export const MAX_AGE_MS = 24 * 60 * 60 * 1000
6	
7	interface CacheEntry {
8	  savedAt: number
9	  works: Artwork[]
10	}
11	
12	export function readCache(now: number): Artwork[] | null {
13	  try {
14	    const saved = window.localStorage.getItem(CACHE_KEY)
15	    if (!saved) return null
16	    const entry = JSON.parse(saved) as Partial<CacheEntry>
17	    if (typeof entry.savedAt !== 'number' || !Array.isArray(entry.works)) return null
18	    if (entry.works.length === 0) return null
19	    if (now - entry.savedAt > MAX_AGE_MS) return null
20	    return entry.works
21	  } catch {
22	    return null
23	  }
24	}
25	
26	export function writeCache(works: Artwork[], now: number): void {
27	  try {
28	    const entry: CacheEntry = { savedAt: now, works }
29	    window.localStorage.setItem(CACHE_KEY, JSON.stringify(entry))
30	  } catch {
31	    // Storage full or blocked: the next visit refetches.
32	  }
33	}
