const PORT = 9333
const APP = 'http://localhost:4173/mp2/'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch {
      // Chrome is still starting.
    }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}

const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.id && waiting.has(message.id)) {
    waiting.get(message.id)(message)
    waiting.delete(message.id)
  }
})
function send(method, params = {}) {
  const id = nextId++
  return new Promise((resolve) => {
    waiting.set(id, resolve)
    socket.send(JSON.stringify({ id, method, params }))
  })
}
async function evaluate(expression) {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}
async function key(char) {
  const code = char.toUpperCase().charCodeAt(0)
  await send('Input.dispatchKeyEvent', { type: 'keyDown', text: char, key: char, windowsVirtualKeyCode: code })
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: char, windowsVirtualKeyCode: code })
}
async function state() {
  return evaluate(`(() => {
    const box = document.querySelector('input[type=search]')
    return {
      box: box && box.value,
      caret: box && box.selectionStart,
      address: location.pathname + location.search,
      rows: document.querySelectorAll('a[href*="/artwork/"]').length,
      summary: document.querySelector('[aria-live=polite]')?.textContent,
    }
  })()`)
}
async function waitFor(check, label) {
  for (let attempt = 0; attempt < 80; attempt++) {
    if (await evaluate(check)) return
    await sleep(250)
  }
  throw new Error('Timed out waiting for ' + label)
}

const results = []
function expect(label, actual, wanted) {
  const ok = JSON.stringify(actual) === JSON.stringify(wanted)
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}: ${JSON.stringify(actual)}${ok ? '' : '  wanted ' + JSON.stringify(wanted)}`)
}

await send('Page.enable')
await send('Page.navigate', { url: APP + '?q=rain' })
await waitFor(`!!document.querySelector('a[href*="/artwork/"]')`, 'the list')
const start = await state()
console.log('start', JSON.stringify(start))

// 1. Type three characters quickly at the start of "rain".
await evaluate(`(() => { const b = document.querySelector('input[type=search]'); b.focus(); b.setSelectionRange(0, 0) })()`)
for (const char of 'xyz') await key(char)
await sleep(300)
let now = await state()
expect('typing at the start keeps order and caret', [now.box, now.caret, now.address], ['xyzrain', 3, '/mp2/?q=xyzrain'])

// 2. Replace the text by typing fast at the end.
await evaluate(`(() => { const b = document.querySelector('input[type=search]'); b.select() })()`)
for (const char of 'monet') await key(char)
await sleep(300)
now = await state()
expect('fast typing replaces the text', [now.box, now.address], ['monet', '/mp2/?q=monet'])
expect('results follow the text', now.rows > 0 && now.rows < start.rows + 50 && /matching “monet”/.test(now.summary), true)

// 3. Open a result, then go back: the search is restored.
await evaluate(`document.querySelector('a[href*="/artwork/"]').click()`)
await waitFor(`location.pathname.includes('/artwork/')`, 'the detail page')
await waitFor(`!!document.querySelector('h1#artwork-title')`, 'the artwork')
const detail = await evaluate(`({ title: document.querySelector('h1').textContent, back: document.querySelector('a[href*="?q=monet"]')?.getAttribute('href') })`)
expect('detail page links back to the search', detail.back, '/mp2/?q=monet')
await evaluate(`history.back()`)
await waitFor(`!!document.querySelector('input[type=search]')`, 'the list again')
await sleep(300)
now = await state()
expect('browser Back restores the search', [now.box, now.address], ['monet', '/mp2/?q=monet'])

// 4. A link that clears the search clears the box.
await evaluate(`[...document.querySelectorAll('nav a')].find((a) => a.textContent === 'List').click()`)
await sleep(300)
now = await state()
expect('the List link clears the box', [now.box, now.address, now.rows], ['', '/mp2/', start.rows > 0 ? now.rows : -1])
expect('the full collection is listed again', now.rows >= 300, true)

// 5. Direct link to a detail page under the base path.
await send('Page.navigate', { url: APP + 'artwork/27992' })
await waitFor(`!!document.querySelector('h1#artwork-title')`, 'a direct link')
expect('direct link shows the artwork', await evaluate(`document.querySelector('h1').textContent`), 'A Sunday on La Grande Jatte — 1884')

socket.close()
const failed = results.filter((ok) => !ok).length
console.log(failed ? `${failed} check(s) failed` : 'all checks passed')
process.exit(failed ? 1 : 0)
"}

