.strip{display:flex;flex:1;justify-content:center;align-items:center;gap:var(--space-2);min-width:0}
.cell{flex:0 1 4.5rem;min-width:0}
.thumb{display:block;width:100%;padding:0;aspect-ratio:1;border:3px solid var(--line);background:var(--line);opacity:.75;transition:opacity .15s ease,transform .15s ease}
.thumb img{width:100%;height:100%;object-fit:cover}
.thumb.current{border-color:var(--accent);opacity:1;transform:scale(1.12)}
@media (max-width:52rem){.body{grid-template-columns:minmax(0,1fr);gap:var(--space-4)}.figure{min-height:14rem;padding:var(--space-3)}}
@media (max-width:40rem){.walk{flex-wrap:wrap;justify-content:space-between}.walk>ul{order:-1;flex:1 0 100%}.fact{grid-template-columns:minmax(0,1fr);gap:0}}

/* ---- Mockup controls (not part of the app) ---- */
.lab{position:sticky;top:0;z-index:5;background:#15130f;color:#f4f0e7;border-bottom:3px solid var(--frame)}
.labInner{max-width:var(--page-width);margin:0 auto;padding:var(--space-3) var(--space-4);display:grid;gap:var(--space-2)}
.labRow{display:flex;flex-wrap:wrap;align-items:center;gap:var(--space-2)}
.labTitle{font-size:var(--text-xs);letter-spacing:.1em;text-transform:uppercase;color:#c9bfa8;margin-right:var(--space-2)}
.pick{padding:var(--space-1) var(--space-3);border:1px solid #6b6455;border-radius:999px;background:transparent;color:#f4f0e7;font-size:var(--text-sm)}
.pick[aria-pressed=true]{background:var(--frame);border-color:var(--frame);color:#15130f;font-weight:600}
.about{font-size:var(--text-sm);color:#d9d0bb;min-height:2.8em;max-width:70rem}
.about b{color:#fff}
.warn{color:#ffb4a8}

/* ---- The transitions ----
   Each names the same three parts. The browser takes a picture of the old and
   new state of each part and animates between them, including the change in
   size of the frame. No inline styles are involved. */
.frame{view-transition-name:artwork}
.label{view-transition-name:label}
.strip{view-transition-name:strip}
.position{view-transition-name:position}
html[data-fx=none] .frame,html[data-fx=none] .label,html[data-fx=none] .strip,html[data-fx=none] .position{view-transition-name:none}

::view-transition-group(*){animation-duration:var(--t);animation-timing-function:cubic-bezier(.22,.7,.2,1)}
::view-transition-old(*),::view-transition-new(*){animation-duration:var(--t);animation-timing-function:cubic-bezier(.22,.7,.2,1)}
::view-transition-old(root),::view-transition-new(root){animation:none}
/* The old and new pictures always fill the frame as it changes size. */
::view-transition-old(artwork),::view-transition-new(artwork){height:100%;width:100%;object-fit:fill}
::view-transition-image-pair(artwork){isolation:auto}

/* A. Morph: the frame reshapes while one picture dissolves into the next. */

/* B. Walk: the picture leaves in the direction you are walking. */
@keyframes out-left{to{transform:translateX(-7%);opacity:0}}
@keyframes in-right{from{transform:translateX(7%);opacity:0}}
@keyframes out-right{to{transform:translateX(7%);opacity:0}}
@keyframes in-left{from{transform:translateX(-7%);opacity:0}}
html[data-fx=walk][data-dir=forward]::view-transition-old(artwork){animation-name:out-left}
html[data-fx=walk][data-dir=forward]::view-transition-new(artwork){animation-name:in-right}
html[data-fx=walk][data-dir=back]::view-transition-old(artwork){animation-name:out-right}
html[data-fx=walk][data-dir=back]::view-transition-new(artwork){animation-name:in-left}
html[data-fx=walk]::view-transition-old(artwork),html[data-fx=walk]::view-transition-new(artwork){mix-blend-mode:normal}

/* C. Dip: the picture fades into the wall, then the next one surfaces. */
@keyframes dip-out{0%{opacity:1}45%,100%{opacity:0}}
@keyframes dip-in{0%,40%{opacity:0}100%{opacity:1}}
html[data-fx=dip]::view-transition-old(artwork){animation-name:dip-out;mix-blend-mode:normal}
html[data-fx=dip]::view-transition-new(artwork){animation-name:dip-in;mix-blend-mode:normal}
html[data-fx=dip]::view-transition-old(label){animation-name:dip-out}
html[data-fx=dip]::view-transition-new(label){animation-name:dip-in}

/* D. Warp: the old picture swells and blurs away; the new one snaps into focus. */
@keyframes warp-out{to{transform:scale(1.09);filter:blur(10px);opacity:0}}
@keyframes warp-in{from{transform:scale(.93);filter:blur(10px);opacity:0}}
html[data-fx=warp]::view-transition-old(artwork){animation-name:warp-out;mix-blend-mode:normal}
html[data-fx=warp]::view-transition-new(artwork){animation-name:warp-in;mix-blend-mode:normal}

/* E. Wipe: the new picture is drawn across the old one. */
@keyframes wipe-forward{from{clip-path:inset(0 0 0 100%)}to{clip-path:inset(0)}}
@keyframes wipe-back{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0)}}
@keyframes hold{from,to{opacity:1}}
html[data-fx=wipe]::view-transition-old(artwork){animation-name:hold;mix-blend-mode:normal}
html[data-fx=wipe]::view-transition-new(artwork){mix-blend-mode:normal}
html[data-fx=wipe][data-dir=forward]::view-transition-new(artwork){animation-name:wipe-forward}
html[data-fx=wipe][data-dir=back]::view-transition-new(artwork){animation-name:wipe-back}

/* Visitors who ask their system for less motion get a plain, quick dissolve. */
@media (prefers-reduced-motion:reduce){
  ::view-transition-group(*),::view-transition-old(*),::view-transition-new(*){animation-duration:120ms !important}
  ::view-transition-old(artwork){animation-name:-ua-view-transition-fade-out !important}
  ::view-transition-new(artwork){animation-name:-ua-view-transition-fade-in !important}
}
</style>
</head>
<body>

<div class="lab" role="region" aria-label="Mockup controls">
  <div class="labInner">
    <div class="labRow">
      <span class="labTitle">Transition</span>
      <button class="pick" data-fx="none">0 · Current (none)</button>
      <button class="pick" data-fx="morph">A · Morph</button>
      <button class="pick" data-fx="walk">B · Walk</button>
      <button class="pick" data-fx="dip">C · Dip</button>
      <button class="pick" data-fx="warp">D · Warp</button>
      <button class="pick" data-fx="wipe">E · Wipe</button>
      <span class="labTitle" id="speedLabel">&nbsp; Speed</span>
      <button class="pick" data-speed="normal">Real (0.34s)</button>
      <button class="pick" data-speed="slow">Slow motion (5×)</button>
    </div>
    <p class="about" id="about"></p>
  </div>
</div>

<header class="header"><div class="bar">
  <div class="brand"><span class="brandMark"></span><span><span class="brandName">The Rooms</span><span class="brandSub">Art Institute of Chicago</span></span></div>
</div></header>

<main class="main">
  <article class="detail">
    <div class="top">
      <a class="back" href="#">← Back to the list</a>
      <p class="position" id="position"></p>
    </div>
    <div class="body">
      <figure class="figure"><div class="frame" id="frame"></div></figure>
      <div class="label">
        <h1 id="title"></h1>
        <dl class="facts" id="facts"></dl>
      </div>
    </div>
    <nav class="walk">
      <button class="step" id="prev">← Previous</button>
      <ul class="strip" id="strip"></ul>
      <button class="step" id="next">Next →</button>
    </nav>
  </article>
</main>

<script>
const WORKS = [
  {id:28560,title:"The Bedroom",artist:"Vincent van Gogh",date:"1889",medium:"Oil on canvas",department:"Painting and Sculpture of Europe",type:"Painting",origin:"Saint-Rémy-de-Provence",style:"Post-Impressionism",image:"6644829f-f292-c5c4-a73c-0356a6fdbf0d"},
  {id:21023,title:"Buddha Shakyamuni Seated in Meditation (Dhyanamudra)",artist:null,date:"Chola period, about 12th century",medium:"Granite",department:"Arts of Asia",type:"Sculpture",origin:"Nagapattinam",style:"South Asian",image:"0675f9a9-1a7b-c90a-3bb6-7f7be2afb678"},
  {id:20684,title:"Paris Street; Rainy Day",artist:"Gustave Caillebotte",date:"1877",medium:"Oil on canvas",department:"Painting and Sculpture of Europe",type:"Painting",origin:"Paris",style:"Impressionism",image:"f8fd76e9-c396-5678-36ed-6a348c904d27"},
  {id:89503,title:"Under the Wave off Kanagawa, also known as The Great Wave",artist:"Katsushika Hokusai",date:"1830/33",medium:"Color woodblock print; oban",department:"Arts of Asia",type:"Print",origin:"Japan",style:"Japanese (culture or style)",image:"2fa24f36-cc26-41b6-4b49-12bba2a6c1c8"},
  {id:16568,title:"Water Lilies",artist:"Claude Monet",date:"1906",medium:"Oil on canvas",department:"Painting and Sculpture of Europe",type:"Painting",origin:"France",style:"Impressionism",image:"3c27b499-af56-f0d5-93b5-a7f2f1ad5813"},
  {id:27992,title:"A Sunday on La Grande Jatte — 1884",artist:"Georges Seurat",date:"1884–86, border added 1888–89",medium:"Oil on canvas",department:"Painting and Sculpture of Europe",type:"Painting",origin:"France",style:"Pointillism",image:"2d484387-2509-5e8e-2c43-22f9981972eb"},
];
const ABOUT = {
  none:  "<b>0 · Current.</b> What the site does today: the old picture is removed, the frame collapses, and the new picture appears when it has loaded. After a picture has been seen once your browser keeps it, so the flash is worst the first time through.",
  morph: "<b>A · Morph.</b> The frame reshapes itself from the old proportions to the new while one picture dissolves into the other. The wall label cross-fades. Closest to the “warp” you described.",
  walk:  "<b>B · Walk.</b> The picture drifts out in the direction you are walking and the next drifts in behind it, as the frame reshapes. Next and Previous move in opposite directions.",
  dip:   "<b>C · Dip.</b> The picture fades into the dark wall, the empty frame reshapes, and the next picture surfaces. The calmest option, with a brief empty frame in the middle.",
  warp:  "<b>D · Warp.</b> The old picture swells and blurs away while the new one shrinks into sharp focus. The most dramatic option.",
  wipe:  "<b>E · Wipe.</b> The new picture is drawn across the old one like a sliding panel, in the direction you are walking.",
};
const $ = (id) => document.getElementById(id);
const root = document.documentElement;
const url = (image, width) => `https://www.artic.edu/iiif/2/${image}/full/${width},/0/default.jpg`;
const supported = typeof document.startViewTransition === "function";
let index = 0;

function picture(work, width) {
  const img = new Image();
  img.referrerPolicy = "no-referrer";
  img.alt = work.title;
  img.src = url(work.image, width);
  return img;
}

// Loaded and decoded ahead of time, so a picture is ready before it is shown.
const ready = new Map();
function preload(i) {
  const work = WORKS[(i + WORKS.length) % WORKS.length];
  if (!ready.has(work.id)) {
    const img = picture(work, 843);
    ready.set(work.id, img.decode().then(() => img, () => img));
  }
  return ready.get(work.id);
}

function fact(name, value) {
  const row = document.createElement("div");
  row.className = "fact";
  const dt = document.createElement("dt"); dt.textContent = name;
  const dd = document.createElement("dd"); dd.textContent = value ?? "Unknown";
  row.append(dt, dd);
  return row;
}

function render(i, img) {
  index = i;
  const work = WORKS[i];
  $("frame").replaceChildren(img ?? picture(work, 843));
  $("title").textContent = work.title;
  $("position").textContent = `${i + 1} of ${WORKS.length}`;
  $("facts").replaceChildren(
    fact("Artist", work.artist), fact("Date", work.date), fact("Medium", work.medium),
    fact("Department", work.department), fact("Type", work.type),
    fact("Place of origin", work.origin), fact("Style", work.style));
  const cells = [-2, -1, 0, 1, 2].map((offset) => {
    const at = (i + offset + WORKS.length) % WORKS.length;
    const li = document.createElement("li"); li.className = "cell";
    const button = document.createElement("button");
    button.className = offset === 0 ? "thumb current" : "thumb";
    button.append(picture(WORKS[at], 200));
    button.addEventListener("click", () => go(at, offset >= 0 ? "forward" : "back"));
    li.append(button);
    return li;
  });
  $("strip").replaceChildren(...cells);
}

async function go(to, direction) {
  const target = (to + WORKS.length) % WORKS.length;
  if (target === index) return;
  root.dataset.dir = direction;
  if (root.dataset.fx === "none" || !supported) {
    ready.delete(WORKS[target].id);
    render(target);
    return;
  }
  const img = (await preload(target)).cloneNode();
  const transition = document.startViewTransition(() => render(target, img));
  transition.finished.then(() => { preload(index + 1); preload(index - 1); });
}

function choose(name, value) {
  root.dataset[name] = value;
  document.querySelectorAll(`.pick[data-${name}]`).forEach((button) =>
    button.setAttribute("aria-pressed", String(button.dataset[name] === value)));
  if (name === "fx") {
    $("about").innerHTML = ABOUT[value] +
      (supported ? "" : ' <span class="warn">This browser does not support these transitions, so it shows the current behaviour. Use Chrome or Edge.</span>');
  }
}

document.querySelectorAll(".pick").forEach((button) =>
  button.addEventListener("click", () =>
    button.dataset.fx ? choose("fx", button.dataset.fx) : choose("speed", button.dataset.speed)));
$("next").addEventListener("click", () => go(index + 1, "forward"));
$("prev").addEventListener("click", () => go(index - 1, "back"));
window.addEventListener("keydown", (event) => {
  if (event.repeat || event.altKey || event.ctrlKey || event.metaKey) return;
  if (event.key === "ArrowRight") go(index + 1, "forward");
  if (event.key === "ArrowLeft") go(index - 1, "back");
});

choose("fx", "morph");
choose("speed", "normal");
render(0);
preload(1); preload(-1);
</script>
</body>
</html>
"}

Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\transitions\check.mjs", "content": "// Opens the mockup in Chrome, runs every transition, and captures a frame
// from the middle of each one in slow motion.
const PORT = 9334
const [, , pageUrl, outDir] = process.argv
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
import { writeFileSync } from 'node:fs'

async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.text + ' ' + (message.params.exceptionDetails.exception?.description ?? ''))
  if (message.method === 'Log.entryAdded' && message.params.entry.level === 'error') errors.push(message.params.entry.text)
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })).result.result.value

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable')
await send('Page.navigate', { url: pageUrl })
await sleep(4000)
console.log('supported:', await evaluate(`typeof document.startViewTransition === 'function'`))
console.log('first picture loaded:', await evaluate(`document.querySelector('#frame img').naturalWidth > 0`))

await evaluate(`document.querySelector('.pick[data-speed=slow]').click()`)
for (const fx of ['morph', 'walk', 'dip', 'warp', 'wipe']) {
  await evaluate(`document.querySelector('.pick[data-fx=${fx}]').click()`)
  const before = await evaluate(`document.getElementById('title').textContent`)
  await evaluate(`document.getElementById('next').click()`)
  await sleep(750)
  const shot = await send('Page.captureScreenshot', { format: 'png' })
  writeFileSync(`${outDir}/mid-${fx}.png`, Buffer.from(shot.result.data, 'base64'))
  const running = await evaluate(`document.getAnimations().length`)
  await sleep(1400)
  const after = await evaluate(`document.getElementById('title').textContent`)
  const size = await evaluate(`(() => { const r = document.getElementById('frame').getBoundingClientRect(); return Math.round(r.width) + 'x' + Math.round(r.height) })()`)
  console.log(`${fx}: "${before.slice(0, 22)}" -> "${after.slice(0, 22)}", animations mid-way ${running}, frame now ${size}`)
}
console.log('inline style attributes on the page:', await evaluate(`document.querySelectorAll('[style]').length`))
console.log('errors:', errors.length ? errors : 'none')
socket.close()
process.exit(0)
"}

