Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\warp_check.mjs", "content": "// Drives the built app in Chrome and checks the transition between artworks.
import { writeFileSync } from 'node:fs'
const PORT = 9335
const [, , outDir] = process.argv
const APP = 'http://localhost:4173/mp2/'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))

async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && message.params.entry.level === 'error') errors.push(message.params.entry.text + ' ' + (message.params.entry.url ?? ''))
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}
async function waitFor(check, label) {
  for (let attempt = 0; attempt < 80; attempt++) {
    if (await evaluate(check)) return
    await sleep(250)
  }
  throw new Error('Timed out waiting for ' + label)
}
const results = []
function expect(label, actual, wanted) {
  const ok = JSON.stringify(actual) === JSON.stringify(wanted)
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}: ${JSON.stringify(actual)}${ok ? '' : '  wanted ' + JSON.stringify(wanted)}`)
}
const page = () => evaluate(`(() => {
  const frame = document.querySelector('figure div').getBoundingClientRect()
  const img = document.querySelector('figure img')
  return {
    title: document.querySelector('h1').textContent,
    address: location.pathname,
    frame: Math.round(frame.width) + 'x' + Math.round(frame.height),
    pictureShown: !!img && img.complete && img.naturalWidth > 0,
  }
})()`)

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable'); await send('Animation.enable')
await send('Page.navigate', { url: APP + 'artwork/28560' })
await waitFor(`!!document.querySelector('h1#artwork-title')`, 'the artwork')
await waitFor(`document.querySelector('figure img')?.naturalWidth > 0`, 'the picture')
await sleep(1500) // let the neighbours' pictures load ahead
const first = await page()
console.log('start', JSON.stringify(first))
expect('browser supports view transitions', await evaluate(`typeof document.startViewTransition === 'function'`), true)

// Watch for the frame ever collapsing or the picture ever being missing.
await evaluate(`(() => {
  window.__watch = { smallest: Infinity, emptyFrames: 0, frames: 0, transitions: 0 }
  const original = document.startViewTransition.bind(document)
  document.startViewTransition = (update) => { window.__watch.transitions++; return original(update) }
  const tick = () => {
    const box = document.querySelector('figure div')
    const img = document.querySelector('figure img')
    if (box) {
      window.__watch.frames++
      window.__watch.smallest = Math.min(window.__watch.smallest, box.getBoundingClientRect().height)
      if (!img || !img.complete || img.naturalWidth === 0) window.__watch.emptyFrames++
    }
    requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
})()`)

// 1. Next, slowed to a fifth of the speed, with a picture from the middle.
await send('Animation.setPlaybackRate', { playbackRate: 0.2 })
await evaluate(`document.querySelector('a[rel=next]').click()`)
await sleep(800)
const midway = await evaluate(`document.getAnimations().filter((a) => a.animationName?.startsWith('artwork-warp')).map((a) => a.animationName).sort()`)
expect('both warp animations run', midway, ['artwork-warp-in', 'artwork-warp-out'])
writeFileSync(`${outDir}/app-mid-warp.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'))
await sleep(1600)
await send('Animation.setPlaybackRate', { playbackRate: 1 })
const second = await page()
expect('Next moved to another artwork', second.address !== first.address && second.title !== first.title, true)
expect('the new picture is shown', second.pictureShown, true)

// 2. Arrow keys, at real speed.
const key = async (name, code) => {
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: name, code: name, windowsVirtualKeyCode: code })
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: name, code: name, windowsVirtualKeyCode: code })
}
await evaluate(`document.body.focus()`)
await key('ArrowLeft', 37)
await sleep(900)
expect('Left arrow returns to the first artwork', (await page()).address, first.address)

// 3. Three fast presses count as three steps.
await key('ArrowRight', 39); await key('ArrowRight', 39); await key('ArrowRight', 39)
await sleep(1800)
const third = await page()
const expected = await evaluate(`JSON.parse(sessionStorage.getItem('mp2.trail.v1') ?? 'null')`)
console.log('after three presses', JSON.stringify(third), expected ? 'trail saved' : 'default order')
await key('ArrowLeft', 37); await key('ArrowLeft', 37); await key('ArrowLeft', 37)
await sleep(1800)
expect('three presses forward and three back return to the start', (await page()).address, first.address)
expect('three presses moved three works away', third.address !== first.address && third.address !== second.address, true)

// 4. A filmstrip thumbnail.
await evaluate(`document.querySelectorAll('ul[aria-label="Neighbouring artworks"] a')[4].click()`)
await sleep(1200)
const fourth = await page()
expect('a filmstrip thumbnail opens its artwork', fourth.address !== first.address && fourth.pictureShown, true)

// 5. Browser Back still works after moving.
await evaluate(`history.back()`)
await sleep(800)
expect('browser Back returns to the artwork before', (await page()).address, first.address)

const watch = await evaluate(`window.__watch`)
console.log('watched', JSON.stringify(watch))
expect('the frame never collapsed', watch.smallest > 150, true)
expect('the frame never showed without its picture', watch.emptyFrames, 0)
expect('every move used a view transition', watch.transitions >= 9, true)
expect('no inline style attributes', await evaluate(`document.querySelectorAll('[style]').length`), 0)
expect('no errors', errors, [])

socket.close()
const failed = results.filter((ok) => !ok).length
console.log(failed ? `${failed} check(s) failed` : 'all checks passed')
process.exit(failed ? 1 : 0)
"}

