CSS = r"""/* ---- The transitions ----
   The picture always uses the Warp already built into the app. The options
   below change only how the words move. */
.frame{view-transition-name:artwork}
.strip{view-transition-name:strip}
.position{view-transition-name:position}
.label{view-transition-name:label}
.label h1{view-transition-name:title}

::view-transition-group(*),::view-transition-old(*),::view-transition-new(*){
  animation-duration:var(--t);animation-timing-function:cubic-bezier(.22,.7,.2,1)}
::view-transition-old(root),::view-transition-new(root){animation:none}
::view-transition-old(artwork),::view-transition-new(artwork){height:100%;width:100%;object-fit:fill;mix-blend-mode:normal}
::view-transition-image-pair(artwork){isolation:auto}
@keyframes warp-out{to{transform:scale(1.09);filter:blur(10px);opacity:0}}
@keyframes warp-in{from{transform:scale(.93);filter:blur(10px);opacity:0}}
::view-transition-old(artwork){animation-name:warp-out}
::view-transition-new(artwork){animation-name:warp-in}

/* 0. As built today: the whole label is one picture that cross-fades. */
html[data-fx=none] .label h1,html[data-fx=none] .fact,html[data-fx=none] .fact dd{view-transition-name:none}

/* In every other option each row and each value moves on its own. The card
   behind them is a separate piece that only changes height. */
html:not([data-fx=none]) .fact{view-transition-class:row}
html:not([data-fx=none]) .fact dd{view-transition-class:value}
html:not([data-fx=none]) .label h1{view-transition-class:value}
.fact[data-key=artist]{view-transition-name:row-artist}
.fact[data-key=date]{view-transition-name:row-date}
.fact[data-key=medium]{view-transition-name:row-medium}
.fact[data-key=department]{view-transition-name:row-department}
.fact[data-key=type]{view-transition-name:row-type}
.fact[data-key=origin]{view-transition-name:row-origin}
.fact[data-key=style]{view-transition-name:row-style}
.fact[data-key=artist] dd{view-transition-name:value-artist}
.fact[data-key=date] dd{view-transition-name:value-date}
.fact[data-key=medium] dd{view-transition-name:value-medium}
.fact[data-key=department] dd{view-transition-name:value-department}
.fact[data-key=type] dd{view-transition-name:value-type}
.fact[data-key=origin] dd{view-transition-name:value-origin}
.fact[data-key=style] dd{view-transition-name:value-style}

/* Words are never stretched: each picture of a value keeps its own size. */
::view-transition-old(.value),::view-transition-new(.value){height:auto;width:100%;mix-blend-mode:normal}
/* A row that stays only glides to its new place; its heading does not blink. */
::view-transition-old(.row):not(:only-child){animation:none;opacity:0}
::view-transition-new(.row):not(:only-child){animation:none}
/* A row that appears or disappears, when the number of facts changes. */
@keyframes row-in{from{opacity:0;transform:translateY(-.6rem) scaleY(.6)}}
@keyframes row-out{to{opacity:0;transform:translateY(-.6rem) scaleY(.6)}}
::view-transition-new(.row):only-child{animation-name:row-in;transform-origin:top}
::view-transition-old(.row):only-child{animation-name:row-out;transform-origin:top}
::view-transition-new(.value):only-child{animation-name:row-in;transform-origin:top}
::view-transition-old(.value):only-child{animation-name:row-out;transform-origin:top}

/* A. Settle: each value dissolves in place. (The browser's own cross-fade.) */

/* B. Cascade: values lift away and new ones rise in, one row after another. */
@keyframes rise-out{to{opacity:0;transform:translateY(-.9rem)}}
@keyframes rise-in{from{opacity:0;transform:translateY(.9rem)}}
html[data-fx=cascade]::view-transition-old(.value):not(:only-child){animation:rise-out calc(var(--t) * .55) cubic-bezier(.4,0,1,1) both}
html[data-fx=cascade]::view-transition-new(.value):not(:only-child){animation:rise-in calc(var(--t) * .7) cubic-bezier(.22,.7,.2,1) both}

/* C. Focus: values blur away and come into focus, like the picture. */
@keyframes focus-out{to{opacity:0;filter:blur(6px);transform:scale(1.04)}}
@keyframes focus-in{from{opacity:0;filter:blur(6px);transform:scale(.97)}}
html[data-fx=focus]::view-transition-old(.value):not(:only-child){animation-name:focus-out;transform-origin:left center}
html[data-fx=focus]::view-transition-new(.value):not(:only-child){animation-name:focus-in;transform-origin:left center}

/* D. Flip: values turn over like the lines of a departures board. */
@keyframes flip-out{to{opacity:0;transform:perspective(30rem) rotateX(88deg)}}
@keyframes flip-in{from{opacity:0;transform:perspective(30rem) rotateX(-88deg)}}
html[data-fx=flip]::view-transition-old(.value):not(:only-child){animation:flip-out calc(var(--t) * .5) cubic-bezier(.4,0,1,1) both;transform-origin:center top}
html[data-fx=flip]::view-transition-new(.value):not(:only-child){animation:flip-in calc(var(--t) * .6) cubic-bezier(.2,.8,.3,1) both;transform-origin:center bottom}

/* E. Slide: values leave and arrive in the direction you are walking. */
@keyframes slide-out-left{to{opacity:0;transform:translateX(-1.6rem)}}
@keyframes slide-in-right{from{opacity:0;transform:translateX(1.6rem)}}
@keyframes slide-out-right{to{opacity:0;transform:translateX(1.6rem)}}
@keyframes slide-in-left{from{opacity:0;transform:translateX(-1.6rem)}}
html[data-fx=slide][data-dir=forward]::view-transition-old(.value):not(:only-child){animation-name:slide-out-left}
html[data-fx=slide][data-dir=forward]::view-transition-new(.value):not(:only-child){animation-name:slide-in-right}
html[data-fx=slide][data-dir=back]::view-transition-old(.value):not(:only-child){animation-name:slide-out-right}
html[data-fx=slide][data-dir=back]::view-transition-new(.value):not(:only-child){animation-name:slide-in-left}

/* B, D and E run down the label, each row a beat after the one above. */
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-new(value-artist){animation-delay:calc(var(--t) * .30)}
