html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-new(value-type){animation-delay:calc(var(--t) * .62)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-new(value-origin){animation-delay:calc(var(--t) * .70)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-new(value-style){animation-delay:calc(var(--t) * .78)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-new(title){animation-delay:calc(var(--t) * .2)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-old(value-date){animation-delay:calc(var(--t) * .05)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-old(value-medium){animation-delay:calc(var(--t) * .10)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-old(value-department){animation-delay:calc(var(--t) * .15)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-old(value-type){animation-delay:calc(var(--t) * .20)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-old(value-origin){animation-delay:calc(var(--t) * .25)}
html:is([data-fx=cascade],[data-fx=flip],[data-fx=slide])::view-transition-old(value-style){animation-delay:calc(var(--t) * .30)}

/* The position counter ticks over in the direction of travel. */
@keyframes tick-out-up{to{opacity:0;transform:translateY(-.7rem)}}
@keyframes tick-in-up{from{opacity:0;transform:translateY(.7rem)}}
@keyframes tick-out-down{to{opacity:0;transform:translateY(.7rem)}}
@keyframes tick-in-down{from{opacity:0;transform:translateY(-.7rem)}}
html:not([data-fx=none])::view-transition-old(position),html:not([data-fx=none])::view-transition-new(position){height:auto;width:auto;right:0;left:auto}
html:not([data-fx=none])[data-dir=forward]::view-transition-old(position){animation-name:tick-out-up}
html:not([data-fx=none])[data-dir=forward]::view-transition-new(position){animation-name:tick-in-up}
html:not([data-fx=none])[data-dir=back]::view-transition-old(position){animation-name:tick-out-down}
html:not([data-fx=none])[data-dir=back]::view-transition-new(position){animation-name:tick-in-down}

@media (prefers-reduced-motion:reduce){
  ::view-transition-group(*),::view-transition-old(*),::view-transition-new(*){animation:none !important}
}
</style>"""

LAB = """<div class="lab" role="region" aria-label="Mockup controls">
  <div class="labInner">
    <div class="labRow">
      <span class="labTitle">Words</span>
      <button class="pick" data-fx="none">0 · As built</button>
      <button class="pick" data-fx="settle">A · Settle</button>
      <button class="pick" data-fx="cascade">B · Cascade</button>
      <button class="pick" data-fx="focus">C · Focus</button>
      <button class="pick" data-fx="flip">D · Flip</button>
      <button class="pick" data-fx="slide">E · Slide</button>
    </div>
    <div class="labRow">
      <span class="labTitle">Missing facts</span>
      <button class="pick" data-gaps="unknown">Shown as “Unknown” (as built)</button>
      <button class="pick" data-gaps="hidden">Left out, so the number of rows changes</button>
      <span class="labTitle">&nbsp; Speed</span>
      <button class="pick" data-speed="normal">Real</button>
      <button class="pick" data-speed="slow">Slow motion (5×)</button>
    </div>
