</div>"""

SCRIPT = r"""<script>
const WORKS = [
  {id:28560,title:"The Bedroom",artist:"Vincent van Gogh",date:"1889",medium:"Oil on canvas",department:"Painting and Sculpture of Europe",type:"Painting",origin:"Saint-Rémy-de-Provence",style:"Post-Impressionism",image:"6644829f-f292-c5c4-a73c-0356a6fdbf0d"},
  {id:185619,title:"Woman's Robe",artist:null,date:"1840/60",medium:"Silk and cotton, plain weave; warp-resist-dyed (ikat); edged with silk twined embroidery",department:"Textiles",type:"Costume and Accessories",origin:"Uzbekistan",style:null,image:"899c5368-d920-d493-05b3-43c875bcce95"},
  {id:20684,title:"Paris Street; Rainy Day",artist:"Gustave Caillebotte",date:"1877",medium:"Oil on canvas",department:"Painting and Sculpture of Europe",type:"Painting",origin:"Paris",style:"Impressionism",image:"f8fd76e9-c396-5678-36ed-6a348c904d27"},
  {id:21023,title:"Buddha Shakyamuni Seated in Meditation (Dhyanamudra)",artist:null,date:"Chola period, about 12th century",medium:"Granite",department:"Arts of Asia",type:"Sculpture",origin:"Nagapattinam",style:"South Asian",image:"0675f9a9-1a7b-c90a-3bb6-7f7be2afb678"},
  {id:11144,title:"Orphrey Band",artist:null,date:"1375/1400",medium:"Linen, plain weave; underlaid with linen, plain weave; embroidered with gilt- and silvered-metal-strip-wrapped silk, linen and silk in knot, overcast, satin, split, and stem stitches; laid work, couching, and hemp, padded couching",department:"Textiles",type:"Textile",origin:"England",style:null,image:"516d9e71-6e59-1e6d-2db0-f29f3b40dd6c"},
  {id:89503,title:"Under the Wave off Kanagawa, also known as The Great Wave",artist:"Katsushika Hokusai",date:"1830/33",medium:"Color woodblock print; oban",department:"Arts of Asia",type:"Print",origin:"Japan",style:"Japanese (culture or style)",image:"2fa24f36-cc26-41b6-4b49-12bba2a6c1c8"},
];
const FACTS = [["artist","Artist"],["date","Date"],["medium","Medium"],["department","Department"],["type","Type"],["origin","Place of origin"],["style","Style"]];
const ABOUT = {
  none:    "<b>0 · As built.</b> The whole label is treated as one picture that cross-fades, so old and new words overlap and the card’s edge jumps.",
  settle:  "<b>A · Settle.</b> Each value dissolves into the next in its own place, rows glide to their new positions, and the card grows or shrinks smoothly. The quietest option.",
  cascade: "<b>B · Cascade.</b> Old values lift away and new ones rise in from below, one row after another down the label.",
  focus:   "<b>C · Focus.</b> Values blur away and come back into focus, all together. It matches the picture’s warp.",
  flip:    "<b>D · Flip.</b> Each value turns over like a line on a departures board, one row after another.",
  slide:   "<b>E · Slide.</b> Values leave and arrive sideways, in the direction you are walking, one row after another.",
};
const $ = (id) => document.getElementById(id);
const root = document.documentElement;
const url = (image, width) => `https://www.artic.edu/iiif/2/${image}/full/${width},/0/default.jpg`;
const supported = typeof document.startViewTransition === "function";
let index = 0;

function picture(work, width) {
  const img = new Image();
  img.referrerPolicy = "no-referrer";
  img.alt = work.title;
  img.src = url(work.image, width);
  return img;
}
const ready = new Map();
function preload(i) {
  const work = WORKS[(i + WORKS.length) % WORKS.length];
  if (!ready.has(work.id)) {
    const img = picture(work, 843);
    ready.set(work.id, img.decode().then(() => img, () => img));
  }
  return ready.get(work.id);
}
function fact(key, name, value) {
  const row = document.createElement("div");
  row.className = "fact";
  row.dataset.key = key;
  const dt = document.createElement("dt"); dt.textContent = name;
  const dd = document.createElement("dd"); dd.textContent = value ?? "Unknown";
  row.append(dt, dd);
  return row;
}
function render(i, img) {
  index = i;
  const work = WORKS[i];
  $("frame").replaceChildren(img ?? picture(work, 843));
  $("title").textContent = work.title;
  $("position").textContent = `${i + 1} of ${WORKS.length}`;
  const hide = root.dataset.gaps === "hidden";
  $("facts").replaceChildren(...FACTS
    .filter(([key]) => !hide || work[key] !== null)
    .map(([key, name]) => fact(key, name, work[key])));
  const cells = [-2, -1, 0, 1, 2].map((offset) => {
    const at = (i + offset + WORKS.length) % WORKS.length;
    const li = document.createElement("li"); li.className = "cell";
    const button = document.createElement("button");
    button.className = offset === 0 ? "thumb current" : "thumb";
    button.append(picture(WORKS[at], 200));
    button.addEventListener("click", () => go(at, offset >= 0 ? "forward" : "back"));
    li.append(button);
    return li;
  });
  $("strip").replaceChildren(...cells);
}
async function go(to, direction) {
  const target = (to + WORKS.length) % WORKS.length;
  if (target === index) return;
  root.dataset.dir = direction;
  const img = (await preload(target)).cloneNode();
  if (!supported) { render(target, img); return; }
  const transition = document.startViewTransition(() => render(target, img));
  transition.ready.catch(() => {});
  transition.finished.then(() => { preload(index + 1); preload(index - 1); }, () => {});
}
function choose(name, value) {
  root.dataset[name] = value;
  document.querySelectorAll(`.pick[data-${name}]`).forEach((button) =>
    button.setAttribute("aria-pressed", String(button.dataset[name] === value)));
  if (name === "fx") {
    $("about").innerHTML = ABOUT[value] +
      (supported ? "" : ' <span class="warn">This browser does not support these transitions. Use Chrome or Edge.</span>');
  }
  if (name === "gaps") render(index);
}
document.querySelectorAll(".pick").forEach((button) =>
  button.addEventListener("click", () => {
    const name = ["fx", "speed", "gaps"].find((key) => key in button.dataset);
    choose(name, button.dataset[name]);
  }));
$("next").addEventListener("click", () => go(index + 1, "forward"));
$("prev").addEventListener("click", () => go(index - 1, "back"));
window.addEventListener("keydown", (event) => {
  if (event.repeat || event.altKey || event.ctrlKey || event.metaKey) return;
  if (event.key === "ArrowRight") go(index + 1, "forward");
  if (event.key === "ArrowLeft") go(index - 1, "back");
});
render(0);
choose("speed", "normal");
choose("gaps", "unknown");
choose("fx", "settle");
preload(1); preload(-1);
</script>"""

page = re.sub(r"/\* ---- The transitions ----.*?</style>", lambda m: CSS, page, count=1, flags=re.S)
page = re.sub(r'<div class="lab".*?</div>\s*</div>\s*</div>', lambda m: LAB, page, count=1, flags=re.S)
page = re.sub(r"<script>.*?</script>", lambda m: SCRIPT, page, count=1, flags=re.S)
