                    'data-fx="settle" data-dir="forward" data-speed="normal" data-gaps="unknown"')
page = page.replace("<title>Transition mockups", "<title>Word transition mockups")
assert page.count('class="lab"') == 1 and page.count("<script>") == 1
(here / "text.html").write_text(page, encoding="utf-8", newline="\n")
print("written", len(page))
"}

Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\transitions\check_text.mjs", "content": "// Runs every word transition in Chrome and captures a frame from the middle.
import { writeFileSync } from 'node:fs'
const PORT = 9336
const [, , pageUrl, outDir] = process.argv
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && ['error', 'warning'].includes(message.params.entry.level)) errors.push(message.params.entry.text)
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => (await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })).result.result.value

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url: pageUrl })
await sleep(4000)
await evaluate(`document.querySelector('.pick[data-speed=slow]').click()`)

for (const gaps of ['unknown', 'hidden']) {
  await evaluate(`document.querySelector('.pick[data-gaps=${gaps}]').click()`)
  for (const fx of ['settle', 'cascade', 'focus', 'flip', 'slide']) {
    await evaluate(`document.querySelector('.pick[data-fx=${fx}]').click()`)
    const before = await evaluate(`document.querySelectorAll('.fact').length`)
    await evaluate(`document.getElementById('next').click()`)
    await sleep(800)
    const names = await evaluate(`[...new Set(document.getAnimations().map((a) => a.animationName).filter(Boolean))].sort().join(', ')`)
    if (gaps === 'hidden' || fx !== 'settle') {
      const shot = await send('Page.captureScreenshot', { format: 'png' })
      writeFileSync(`${outDir}/text-${gaps}-${fx}.png`, Buffer.from(shot.result.data, 'base64'))
    }
    await sleep(2200)
    const after = await evaluate(`document.querySelectorAll('.fact').length`)
    console.log(`${gaps} / ${fx}: rows ${before} -> ${after}; running mid-way: ${names}`)
  }
}
console.log('inline style attributes:', await evaluate(`document.querySelectorAll('[style]').length`))
console.log('errors or warnings:', errors.length ? errors : 'none')
socket.close()
process.exit(0)
"}

