Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\transitions\check_slide.mjs", "content": "// Checks that words travel the right way for Next, Previous, arrow keys and
// the filmstrip, in both senses, by reading the animations Chrome is running.
import { writeFileSync } from 'node:fs'
const PORT = 9337
const [, , pageUrl, outDir] = process.argv
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && ['error', 'warning'].includes(message.params.entry.level)) errors.push(message.params.entry.text)
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}
const key = async (name, code) => {
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: name, code: name, windowsVirtualKeyCode: code })
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: name, code: name, windowsVirtualKeyCode: code })
}
// What each part of the page is doing, by the pseudo-element it belongs to.
const running = () => evaluate(`(() => {
  const found = {}
  for (const a of document.getAnimations()) {
    const pseudo = a.effect?.pseudoElement ?? ''
    const name = a.animationName ?? ''
    if (name.startsWith('-ua-')) continue
    const part = pseudo.replace('::view-transition-', '')
    if (/artist|position|artwork|title/.test(part)) found[part] = name
  }
  return found
})()`)
const results = []
function expect(label, actual, wanted) {
  const ok = Object.entries(wanted).every(([part, name]) => actual[part] === name)
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}`)
  if (!ok) console.log('      got   ', JSON.stringify(actual), '\n      wanted', JSON.stringify(wanted))
}
const LEFTWARDS = { 'old(value-artist)': 'slide-out-left', 'new(value-artist)': 'slide-in-right', 'old(title)': 'slide-out-left', 'new(title)': 'slide-in-right', 'old(position)': 'slide-out-left', 'new(position)': 'slide-in-right' }
const RIGHTWARDS = { 'old(value-artist)': 'slide-out-right', 'new(value-artist)': 'slide-in-left', 'old(title)': 'slide-out-right', 'new(title)': 'slide-in-left', 'old(position)': 'slide-out-right', 'new(position)': 'slide-in-left' }

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url: pageUrl })
await sleep(4000)
await evaluate(`document.querySelector('.pick[data-speed=slow]').click()`)

async function step(label, action, wanted, shot) {
  await action()
  await sleep(700)
  expect(label, await running(), wanted)
  if (shot) writeFileSync(`${outDir}/${shot}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'))
  await sleep(2300)
}
const click = (selector) => () => evaluate(`document.querySelector('${selector}').click()`)
const thumb = (n) => () => evaluate(`document.querySelectorAll('#strip button')[${n}].click()`)

console.log('-- Next brings words in from the right --')
await step('Next button: words travel left', click('#next'), LEFTWARDS, 'slide-next')
await step('Previous button: words travel right', click('#prev'), RIGHTWARDS, 'slide-previous')
await step('Right arrow key: words travel left', () => key('ArrowRight', 39), LEFTWARDS)
await step('Left arrow key: words travel right', () => key('ArrowLeft', 37), RIGHTWARDS)
await step('Filmstrip, a work to the right: words travel left', thumb(4), LEFTWARDS)
await step('Filmstrip, a work to the left: words travel right', thumb(0), RIGHTWARDS)

console.log('-- with the picture leaning --')
await evaluate(`document.querySelector('.pick[data-lean=on]').click()`)
await step('Next: picture leans left with the words', click('#next'), { ...LEFTWARDS, 'old(artwork)': 'lean-out-left', 'new(artwork)': 'lean-in-right' }, 'slide-lean-next')
await step('Previous: picture leans right with the words', click('#prev'), { ...RIGHTWARDS, 'old(artwork)': 'lean-out-right', 'new(artwork)': 'lean-in-left' })
await evaluate(`document.querySelector('.pick[data-lean=off]').click()`)
await step('Picture back to warping in place', click('#next'), { ...LEFTWARDS, 'old(artwork)': 'warp-out', 'new(artwork)': 'warp-in' })

console.log('-- Next brings words in from the left --')
await evaluate(`document.querySelector('.pick[data-sense=reverse]').click()`)
await step('Next button: words travel right', click('#next'), RIGHTWARDS)
await step('Previous button: words travel left', click('#prev'), LEFTWARDS)

console.log('inline style attributes:', await evaluate(`document.querySelectorAll('[style]').length`))
console.log('errors or warnings:', errors.length ? errors : 'none')
socket.close()
const failed = results.filter((ok) => !ok).length
console.log(failed ? `${failed} check(s) failed` : 'all checks passed')
process.exit(0)
"}

