Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\slide_check.mjs", "content": "// Drives the built app in Chrome and reads back which way each part moves.
import { writeFileSync } from 'node:fs'
const PORT = 9338
const [, , outDir] = process.argv
const APP = 'http://localhost:4173/mp2/'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && ['error', 'warning'].includes(message.params.entry.level)) errors.push(message.params.entry.text + ' ' + (message.params.entry.url ?? ''))
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}
async function waitFor(check, label) {
  for (let attempt = 0; attempt < 80; attempt++) {
    if (await evaluate(check)) return
    await sleep(250)
  }
  throw new Error('Timed out waiting for ' + label)
}
const key = async (name, code) => {
  await send('Input.dispatchKeyEvent', { type: 'keyDown', key: name, code: name, windowsVirtualKeyCode: code })
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: name, code: name, windowsVirtualKeyCode: code })
}
const running = () => evaluate(`(() => {
  const found = {}
  for (const a of document.getAnimations()) {
    const name = a.animationName ?? ''
    if (!name || name.startsWith('-ua-')) continue
    found[(a.effect?.pseudoElement ?? '').replace('::view-transition-', '')] = name
  }
  return found
})()`)
const results = []
function check(label, ok, detail) {
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : '\n      ' + detail}`)
}
function expectParts(label, actual, wanted) {
  const ok = Object.entries(wanted).every(([part, name]) => actual[part] === name)
  check(label, ok, 'got ' + JSON.stringify(actual))
}
const VALUES = ['artist', 'date', 'medium', 'department', 'type', 'origin', 'style']
const parts = (out, into, pictureOut, pictureIn) => ({
  'old(artwork)': pictureOut, 'new(artwork)': pictureIn,
  'old(artwork-title)': out, 'new(artwork-title)': into,
  'old(artwork-position)': out, 'new(artwork-position)': into,
  ...Object.fromEntries(VALUES.flatMap((v) => [[`old(artwork-value-${v})`, out], [`new(artwork-value-${v})`, into]])),
})
const FORWARD = parts('words-leave-left', 'words-arrive-from-right', 'artwork-leave-left', 'artwork-arrive-from-right')
const BACK = parts('words-leave-right', 'words-arrive-from-left', 'artwork-leave-right', 'artwork-arrive-from-left')
const title = () => evaluate(`document.querySelector('h1').textContent`)

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable'); await send('Animation.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url: APP + 'artwork/28560' })
await waitFor(`!!document.querySelector('h1#artwork-title')`, 'the artwork')
await waitFor(`document.querySelector('figure img')?.naturalWidth > 0`, 'the picture')
await sleep(1500)
const start = await title()

async function step(label, action, wanted, shot) {
  await send('Animation.setPlaybackRate', { playbackRate: 0.2 })
  const before = await title()
  await action()
  await sleep(650)
  expectParts(label, await running(), wanted)
  if (shot) writeFileSync(`${outDir}/${shot}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'))
  await sleep(1700)
  await send('Animation.setPlaybackRate', { playbackRate: 1 })
  check(`   ...and the artwork changed`, (await title()) !== before, 'still ' + before)
  check(`   ...with seven facts shown`, (await evaluate(`document.querySelectorAll('dl > div').length`)) === 7, '')
}
await evaluate(`document.body.focus()`)
await step('Next: words and picture travel left', () => evaluate(`document.querySelector('a[rel=next]').click()`), FORWARD, 'app-slide-next')
await step('Previous: words and picture travel right', () => evaluate(`document.querySelector('a[rel=prev]').click()`), BACK, 'app-slide-previous')
check('back at the first artwork', (await title()) === start, await title())
await step('Right arrow key: travel left', () => key('ArrowRight', 39), FORWARD)
await step('Left arrow key: travel right', () => key('ArrowLeft', 37), BACK)
await step('Filmstrip, thumbnail on the right: travel left', () => evaluate(`document.querySelectorAll('ul[aria-label="Neighbouring artworks"] a')[4].click()`), FORWARD)
await step('Filmstrip, thumbnail on the left: travel right', () => evaluate(`document.querySelectorAll('ul[aria-label="Neighbouring artworks"] a')[0].click()`), BACK)

// A work with a missing fact keeps its row.
await send('Page.navigate', { url: APP + 'artwork/11144' })
await waitFor(`!!document.querySelector('h1#artwork-title')`, 'Orphrey Band')
await waitFor(`document.querySelector('figure img')?.naturalWidth > 0`, 'its picture')
const unknowns = await evaluate(`[...document.querySelectorAll('dl dd')].filter((dd) => dd.textContent === 'Unknown').length`)
check('a work with two missing facts shows them as Unknown', unknowns === 2 && (await evaluate(`document.querySelectorAll('dl > div').length`)) === 7, String(unknowns))
check('its small picture is shown', await evaluate(`document.querySelector('figure img').naturalWidth === 398`), '')

// Words must never be left hidden or shifted once the move is over.
await sleep(800)
const settled = await evaluate(`(() => [...document.querySelectorAll('h1, dl dd')].every((el) => {
  const box = el.getBoundingClientRect()
  return box.width > 0 && getComputedStyle(el).opacity === '1'
}) && document.getAnimations().length === 0)()`)
check('nothing is left hidden or still moving afterwards', settled, '')
check('no inline style attributes', (await evaluate(`document.querySelectorAll('[style]').length`)) === 0, '')
check('no errors or warnings', errors.length === 0, JSON.stringify(errors))

socket.close()
const failed = results.filter((ok) => !ok).length
console.log(failed ? `${failed} check(s) failed` : `all ${results.length} checks passed`)
process.exit(failed ? 1 : 0)
"}

import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import { BrowserRouter } from 'react-router-dom'
import 'normalize.css'
import './styles/tokens.css'
import './index.css'
import './styles/transitions.css'
import App from './App.tsx'
import { CollectionProvider } from './collection/CollectionProvider.tsx'

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    {/* Address changes apply at once, so the search box and the address
        never disagree while typing. */}
    <BrowserRouter basename={import.meta.env.BASE_URL} useTransitions={false}>
      <CollectionProvider>
        <App />
      </CollectionProvider>
    </BrowserRouter>
  </StrictMode>,
)
import { Route, Routes } from 'react-router-dom'
import { Layout } from './components/Layout'
import { DetailView } from './views/DetailView'
import { ListView } from './views/ListView'
import { NotFound } from './views/NotFound'
import { RoomsView } from './views/RoomsView'
import { TimelineView } from './views/TimelineView'

function App() {
  return (
    <Routes>
      <Route element={<Layout />}>
        <Route index element={<ListView />} />
        <Route path="rooms" element={<RoomsView />} />
        <Route path="timeline" element={<TimelineView />} />
        <Route path="artwork/:id" element={<DetailView />} />
        <Route path="*" element={<NotFound />} />
      </Route>
    </Routes>
  )
}

export default App
import axios, { isAxiosError } from 'axios'
import type { AxiosAdapter, AxiosRequestConfig } from 'axios'
import type { Artwork } from '../types/artwork'

const API_BASE = 'https://api.artic.edu/api/v1'
const IIIF_BASE = 'https://www.artic.edu/iiif/2'
const TIMEOUT_MS = 8000

export const STARTER_PER_DEPARTMENT = 30
export const SEARCH_LIMIT = 100

const FIELDS = [
  'id',
  'title',
  'artist_title',
  'date_start',
  'date_display',
  'medium_display',
  'department_title',
  'artwork_type_title',
  'place_of_origin',
  'style_title',
  'image_id',
  'is_public_domain',
].join(',')

interface ApiArtwork {
  id: number
  title?: string | null
  artist_title?: string | null
  date_start?: number | null
  date_display?: string | null
  medium_display?: string | null
  department_title?: string | null
  artwork_type_title?: string | null
  place_of_origin?: string | null
  style_title?: string | null
  image_id?: string | null
  is_public_domain?: boolean
}

export class ApiError extends Error {}

const PUBLIC_WITH_IMAGE = [
  { term: { is_public_domain: true } },
  { exists: { field: 'image_id' } },
]

function text(value: string | null | undefined): string | null {
  const trimmed = value?.trim()
  return trimmed ? trimmed : null
}

function toArtwork(raw: ApiArtwork): Artwork | null {
  const imageId = text(raw.image_id)
  if (!imageId) return null
  return {
    id: raw.id,
    title: text(raw.title),
    artist: text(raw.artist_title),
    year: typeof raw.date_start === 'number' ? raw.date_start : null,
    dateDisplay: text(raw.date_display),
    medium: text(raw.medium_display),
    department: text(raw.department_title),
    artworkType: text(raw.artwork_type_title),
    placeOfOrigin: text(raw.place_of_origin),
    style: text(raw.style_title),
    imageId,
  }
}

function toArtworks(raws: ApiArtwork[] | undefined): Artwork[] {
  return (raws ?? []).flatMap((raw) => toArtwork(raw) ?? [])
}

function displayable(error: unknown): ApiError {
  if (isAxiosError(error) && error.response) {
    return new ApiError(
      `The Art Institute API returned an error (${error.response.status}).`,
    )
  }
  return new ApiError(
    'Could not reach the Art Institute API. Check your connection and try again.',
  )
}

export type ImageSize = 'thumb' | 'thumb-fit' | 'full'

/**
 * The museum never enlarges a picture, and refuses a request that would. A
 * size such as "843," asks for that exact width, so it fails for a smaller
 * original; "!843,843" asks for the best fit within that box and always works.
 */
const IMAGE_SIZES: Record<ImageSize, string> = {
  thumb: '200,',
  'thumb-fit': '!200,200',
  full: '!843,843',
}

export function imageUrl(imageId: string, size: ImageSize): string {
  return `${IIIF_BASE}/${imageId}/full/${IMAGE_SIZES[size]}/0/default.jpg`
}

