const OUT = 'C:/Users/User/AppData/Local/Temp/claude/C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2/2b80a059-753f-4620-b4b4-896dc263c6f9/scratchpad/critic-ego/shots'
