const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
function log(...args) { const line = args.map(a => typeof a === 'string' ? a : JSON.stringify(a)).join(' '); console.log(line); appendFileSync(LOG, line + '\n') }

async function target() {
  for (let i = 0; i < 40; i++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find(p => p.type === 'page')
      if (page) return page
    } catch {}
    await sleep(250)
  }
  throw new Error('no page')
}
const page = await target()
const socket = new WebSocket(page.webSocketDebuggerUrl)
await new Promise((res) => socket.addEventListener('open', res))
let nextId = 1
const waiting = new Map()
const consoleMsgs = []
const netReqs = []
const netFail = []
socket.addEventListener('message', (event) => {
  const m = JSON.parse(event.data)
  if (m.method === 'Runtime.consoleAPICalled') consoleMsgs.push(m.params.type + ': ' + (m.params.args||[]).map(a=>a.value??a.description).join(' '))
  if (m.method === 'Runtime.exceptionThrown') consoleMsgs.push('EXCEPTION: ' + (m.params.exceptionDetails.exception?.description ?? m.params.exceptionDetails.text))
  if (m.method === 'Network.responseReceived') netReqs.push({url: m.params.response.url, status: m.params.response.status, type: m.params.type, size: m.params.response.encodedDataLength})
  if (m.method === 'Network.loadingFailed') netFail.push(m.params)
  if (m.id && waiting.has(m.id)) { waiting.get(m.id)(m); waiting.delete(m.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) { log('EVAL ERROR', JSON.stringify(reply.result.exceptionDetails)); return null }
  return reply.result.result.value
}
async function waitFor(check, label, tries=60) {
  for (let i = 0; i < tries; i++) {
    if (await evaluate(check)) return true
    await sleep(250)
  }
  log('TIMEOUT waiting for', label)
  return false
}
async function shot(name) {
  const r = await send('Page.captureScreenshot', { format: 'png' })
  writeFileSync(`${OUT}/${name}.png`, Buffer.from(r.result.data, 'base64'))
  log('shot saved', name)
}
