function sortedCheck(arr, idx, dir, numeric) {
  const vals = arr.map((x) => x[idx])
  let bad = 0
  for (let i = 1; i < vals.length; i++) {
    let a = vals[i - 1], b = vals[i]
    let cmp
    if (numeric) { const na = parseInt(a), nb = parseInt(b); if (isNaN(na) || isNaN(nb)) continue; cmp = na - nb; if (/BCE|BC/.test(a)) {} }
    else cmp = a.localeCompare(b, undefined, { sensitivity: 'base' })
    if (dir === 'asc' ? cmp > 0 : cmp < 0) bad++
  }
  return bad
}
for (const [key, idx, num] of [['title', 0, false], ['artist', 1, false], ['year', 2, true]]) {
  for (const dir of ['asc', 'desc']) {
    await c.ev(`(()=>{const s=document.querySelector('select');const set=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set;set.call(s,'${key}');s.dispatchEvent(new Event('change',{bubbles:true}))})()`)
    await c.ev(`[...document.querySelectorAll('fieldset button')].find(b=>b.textContent.startsWith('${dir === 'asc' ? 'Asc' : 'Desc'}')).click()`)
    await sleep(300)
    r = await c.ev(rows)
    console.log(`SORT ${key} ${dir}: out-of-order pairs=${sortedCheck(r, idx, dir, num)} first3=${JSON.stringify(r.slice(0, 3).map((x) => x[idx]))} last3=${JSON.stringify(r.slice(-3).map((x) => x[idx]))} url=${await c.ev('location.search')}`)
  }
}
