  console.log(`typed -> box=${JSON.stringify(await c.ev(`document.querySelector('input[type=search]').value`))} rows=${(await c.ev(rows)).length} ${await c.ev(summary)}`)
}
console.log('monet rows', JSON.stringify((await c.ev(rows)).slice(0, 5)))
// odd inputs
for (const q of ['   ', '(', '.*', '\\', '%', 'MONET', 'claude monet', 'monet claude', 'Mönet', 'water lilies', '1890', '🙂', 'a'.repeat(500), '<img src=x onerror=alert(1)>']) {
  await c.send('Page.navigate', { url: APP + '?q=' + encodeURIComponent(q) })
  await c.waitFor(`document.querySelector('input[type=search]') && !document.body.textContent.includes('Loading the collection')`, 'list ' + q)
  await sleep(300)
  console.log(`q=${JSON.stringify(q.slice(0, 30))} rows=${(await c.ev(rows)).length} summary=${(await c.ev(summary) || '').slice(0, 80)} box=${JSON.stringify((await c.ev(`document.querySelector('input[type=search]')?.value`) || '').slice(0, 30))}`)
}
// search full museum button
await c.send('Page.navigate', { url: APP + '?q=lilies' })
await c.waitFor(`document.querySelector('input[type=search]') && !document.body.textContent.includes('Loading the collection')`, 'list')
await sleep(300)
console.log('lilies local rows', (await c.ev(rows)).length)
await c.ev(`[...document.querySelectorAll('button')].find(b=>b.textContent.includes('full museum')).click()`)
await c.waitFor(`!document.body.textContent.includes('Searching the full museum')`, 'museum search')
await sleep(500)
console.log('after museum search rows', (await c.ev(rows)).length, (await c.ev(`[...document.querySelectorAll('[role=status],[role=alert]')].map(e=>e.textContent).join(' || ')`)))
// garbage url params
await c.send('Page.navigate', { url: APP + '?sort=bogus&dir=sideways' })
await c.waitFor(`document.querySelectorAll('ol li a').length>0`, 'list')
