await waitFor(`document.body.innerText.length > 50`)
await sleep(1200)

function luminance([r,g,b]) {
  const a = [r,g,b].map(v => { v/=255; return v<=0.03928? v/12.92 : Math.pow((v+0.055)/1.055,2.4) })
  return 0.2126*a[0]+0.7152*a[1]+0.0722*a[2]
}
function contrast(c1,c2){ const L1=luminance(c1),L2=luminance(c2); const [a,b]=L1>L2?[L1,L2]:[L2,L1]; return (a+0.05)/(b+0.05) }

const colorChecks = await evaluate(`(() => {
  function parseColor(str) {
    const m = str.match(/rgba?\\(([^)]+)\\)/); if(!m) return null;
    return m[1].split(',').slice(0,3).map(s=>parseFloat(s));
  }
  function effectiveBg(el) {
    let e = el;
    while (e) {
      const c = getComputedStyle(e).backgroundColor;
      const rgb = parseColor(c);
      if (rgb && !(c.includes('rgba') && c.trim().endsWith(', 0)'))) return rgb;
      e = e.parentElement;
    }
    return [255,255,255];
  }
  const targets = [];
  document.querySelectorAll('nav a, .sortby, select, h1, p, dd, dt, footer, footer a, small, [class*=meta], [class*=subtitle], [class*=year], [class*=artist]').forEach(el => {
    if (targets.length > 40) return;
    const txt = el.textContent.trim().slice(0,30);
    if (!txt) return;
    const cs = getComputedStyle(el);
    const fg = parseColor(cs.color);
    if (!fg) return;
    targets.push({ tag: el.tagName, cls: el.className.toString().slice(0,40), text: txt, fg, bg: effectiveBg(el), fontSize: cs.fontSize, fontWeight: cs.fontWeight });
