})()`)
for (const t of colorChecks) {
  const ratio = contrast(t.fg, t.bg)
  log('CONTRAST', ratio.toFixed(2), t.tag, t.cls, JSON.stringify(t.text), 'fg='+t.fg, 'bg='+t.bg, t.fontSize, t.fontWeight)
}

