    "text": "/*
 * Moving between artworks on the detail page.
 *
 * The frame, the wall label's card, its title, each row and each value, the
 * position and the filmstrip are given view-transition names where they are
 * styled. The browser pictures each one before and after the change and
 * animates between the two.
 *
 * The page says which way it is travelling with data-travel on the root
 * element: "forward" for Next, "back" for Previous. Going forward, what you
 * pass leaves to the left and what you reach arrives from the right, as if
 * walking along the wall.
 */

:root {
  --artwork-step: 340ms;
  --artwork-ease: cubic-bezier(0.22, 0.7, 0.2, 1);
}

::view-transition-group(*),
::view-transition-old(*),
::view-transition-new(*) {
  animation-duration: var(--artwork-step);
  animation-timing-function: var(--artwork-ease);
}

/* Only the named parts move; the rest of the page stays still. */
::view-transition-old(root),
::view-transition-new(root) {
  animation: none;
}

/* ---- The picture: it warps, leaning the way the page is travelling ---- */

/* The old and new pictures fill the frame while it changes size. */
::view-transition-old(artwork),
::view-transition-new(artwork) {
  width: 100%;
  height: 100%;
  object-fit: fill;
  mix-blend-mode: normal;
}

::view-transition-image-pair(artwork) {
  isolation: auto;
}

::view-transition-old(artwork) {
  animation-name: artwork-leave-left;
}

::view-transition-new(artwork) {
  animation-name: artwork-arrive-from-right;
}

:root[data-travel='back']::view-transition-old(artwork) {
  animation-name: artwork-leave-right;
}

:root[data-travel='back']::view-transition-new(artwork) {
  animation-name: artwork-arrive-from-left;
}

@keyframes artwork-leave-left {
  to {
    transform: translateX(-5%) scale(1.09);
    filter: blur(10px);
    opacity: 0;
  }
}

@keyframes artwork-arrive-from-right {
  from {
    transform: translateX(5%) scale(0.93);
    filter: blur(10px);
    opacity: 0;
  }
}

@keyframes artwork-leave-right {
  to {
    transform: translateX(5%) scale(1.09);
    filter: blur(10px);
    opacity: 0;
  }
}

@keyframes artwork-arrive-from-left {
  from {
    transform: translateX(-5%) scale(0.93);
    filter: blur(10px);
    opacity: 0;
  }
}

/* ---- The wall label ---- */

/* The card is only a background, so it stretches to its new height. */
::view-transition-old(artwork-label),
::view-transition-new(artwork-label) {
  width: 100%;
  height: 100%;
  object-fit: fill;
}

/* A row glides to its new place; its heading does not blink. */
::view-transition-old(.artwork-row) {
  animation: none;
  opacity: 0;
}

::view-transition-new(.artwork-row) {
  animation: none;
}

/* Words slide, and are never stretched. */
::view-transition-old(.artwork-words),
::view-transition-new(.artwork-words) {
  width: 100%;
  height: auto;
  mix-blend-mode: normal;
}

::view-transition-old(.artwork-words) {
  animation-name: words-leave-left;
}

::view-transition-new(.artwork-words) {
  animation-name: words-arrive-from-right;
}

:root[data-travel='back']::view-transition-old(.artwork-words) {
  animation-name: words-leave-right;
}

:root[data-travel='back']::view-transition-new(.artwork-words) {
  animation-name: words-arrive-from-left;
}

@keyframes words-leave-left {
