Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\transitions\check_overlap.mjs", "content": "// For each way of handling the words, samples the transition many times and
// measures how much old and new text is visible at the same moment.
import { writeFileSync } from 'node:fs'
const PORT = 9339
const [, , pageUrl, outDir] = process.argv
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && ['error', 'warning'].includes(message.params.entry.level)) errors.push(message.params.entry.text)
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 1000, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url: pageUrl })
await sleep(4000)

// Reads, from the running animations, how visible the old and the new picture
// of one part are at this instant (0 = unseen, 1 = fully seen).
const SAMPLE = `(() => {
  const seen = {}
  for (const a of document.getAnimations()) {
    const pseudo = a.effect?.pseudoElement ?? ''
    const match = pseudo.match(/::view-transition-(old|new)\\((title|position|value-[a-z]+)\\)/)
    if (!match) continue
    const opacity = Number(getComputedStyle(document.documentElement, pseudo).opacity)
    const key = match[2]
    seen[key] = seen[key] ?? {}
    seen[key][match[1]] = Math.min(seen[key][match[1]] ?? 1, opacity)
  }
  return seen
})()`

const out = []
for (const mode of ['asbuilt', 'quickfade', 'headline', 'handoff', 'together']) {
  await evaluate(`document.querySelector('.pick[data-speed=normal]').click()`)
  await evaluate(`document.querySelector('.pick[data-mode=${mode}]').click()`)
  // Measure at real speed: start a move, then sample every animation frame.
  const measured = await evaluate(`new Promise((resolve) => {
    const started = performance.now()
    let worstTitle = 0, worstFact = 0, overlapMs = 0, last = started, ended = started, sawAny = false
    const sample = ${SAMPLE.replace(/`/g, '\\`')}
    const tick = () => {
      const now = performance.now()
      const seen = (${SAMPLE.replace(/`/g, '\\`')})
      const keys = Object.keys(seen)
      if (keys.length) { sawAny = true; ended = now }
      let overlapping = false
      for (const key of keys) {
        const both = Math.min(seen[key].old ?? 0, seen[key].new ?? 0)
        if (key === 'title' || key === 'position') worstTitle = Math.max(worstTitle, both)
        else worstFact = Math.max(worstFact, both)
        if (both > 0.15) overlapping = true
      }
      if (overlapping) overlapMs += now - last
      last = now
      if (now - started > 1500) resolve({ worstTitle, worstFact, overlapMs: Math.round(overlapMs), lengthMs: Math.round(ended - started), sawAny })
      else requestAnimationFrame(tick)
    }
    document.getElementById('next').click()
    requestAnimationFrame(tick)
  })`)
  // A picture from the middle, in slow motion, of the move back again.
  await evaluate(`document.querySelector('.pick[data-speed=slow]').click()`)
  await evaluate(`document.getElementById('next').click()`)
  await sleep(760)
  writeFileSync(`${outDir}/overlap-${mode}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png', clip: { x: 740, y: 215, width: 540, height: 480, scale: 1 } })).result.data, 'base64'))
  await sleep(2400)
  out.push({ mode, ...measured })
  console.log(`${mode.padEnd(10)} length ${String(measured.lengthMs).padStart(4)} ms | both readable for ${String(measured.overlapMs).padStart(3)} ms | worst overlap: title ${measured.worstTitle.toFixed(2)}, facts ${measured.worstFact.toFixed(2)}`)
}
console.log('inline style attributes:', await evaluate(`document.querySelectorAll('[style]').length`))
console.log('errors or warnings:', errors.length ? errors : 'none')
socket.close()
process.exit(0)
"}

