import { writeFileSync } from 'node:fs'
const PORT = 9340
const [, , outDir] = process.argv
const APP = 'http://localhost:4173/mp2/'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && ['error', 'warning'].includes(message.params.entry.level)) errors.push(message.params.entry.text + ' ' + (message.params.entry.url ?? ''))
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}
async function waitFor(check, label) {
  for (let attempt = 0; attempt < 80; attempt++) {
    if (await evaluate(check)) return
    await sleep(250)
  }
  throw new Error('Timed out waiting for ' + label)
}
const results = []
function check(label, ok, detail = '') {
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : '  -> ' + detail}`)
}
const shot = async (name) => writeFileSync(`${outDir}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'))
const position = () => evaluate(`document.querySelector('article p')?.textContent ?? ''`)

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false })

// 1. Fast clicking.
await send('Page.navigate', { url: APP + 'artwork/28560' })
await waitFor(`!!document.querySelector('h1#artwork-title')`, 'the artwork')
await waitFor(`document.querySelector('figure img')?.naturalWidth > 0`, 'the picture')
await sleep(1200)
check('starts at 1 of 330', (await position()) === '1 of 330', await position())
for (const [gap, clicks, selector, wanted] of [[40, 10, 'a[rel=next]', '11 of 330'], [40, 4, 'a[rel=prev]', '7 of 330'], [120, 5, 'a[rel=next]', '12 of 330']]) {
  await evaluate(`new Promise((resolve) => {
    let n = 0
    const timer = setInterval(() => {
      document.querySelector('${selector}').click()
      if (++n === ${clicks}) { clearInterval(timer); resolve() }
    }, ${gap})
  })`)
  await waitFor(`document.getAnimations().length === 0 && !!document.querySelector('figure img')?.complete`, 'the page to settle')
  await sleep(1800)
  const now = await position()
  check(`${clicks} clicks ${gap} ms apart on ${selector === 'a[rel=next]' ? 'Next' : 'Previous'} lands on ${wanted}`, now === wanted, now)
}
check('the picture is shown after fast clicking', await evaluate(`document.querySelector('figure img').naturalWidth > 0`))

// 2. The public-domain explanation.
await send('Page.navigate', { url: APP + '?q=picasso' })
await waitFor(`/artworks? matching/.test(document.body.innerText)`, 'the list')
const text = await evaluate(`document.querySelector('main').innerText`)
check('an empty search explains the public-domain limit', /only works in the public domain/.test(text) && /still in copyright/.test(text), text.slice(0, 200))
await shot('fix-empty-search')
await evaluate(`[...document.querySelectorAll('button')].find((b) => /full museum/.test(b.textContent)).click()`)
await waitFor(`/The full museum (has no|returned)/.test(document.body.innerText)`, 'the museum search')
const after = await evaluate(`document.querySelector('main').innerText`)
console.log('      museum says:', after.match(/The full museum[^\n]*/)?.[0])
await send('Page.navigate', { url: APP + '?q=monet' })
await waitFor(`/artworks? matching/.test(document.body.innerText)`, 'the list')
check('a search with results does not mention copyright', !/still in copyright/.test(await evaluate(`document.querySelector('main').innerText`)))

// 3. The filter rows on a phone.
await send('Emulation.setDeviceMetricsOverride', { width: 375, height: 800, deviceScaleFactor: 2, mobile: true })
await send('Page.navigate', { url: APP + 'rooms' })
await waitFor(`!!document.querySelector('fieldset')`, 'the filters')
await sleep(800)
const hints = await evaluate(`[...document.querySelectorAll('fieldset p')].map((p) => getComputedStyle(p).display)`)
check('the scroll hint shows on a phone', hints.length === 2 && hints.every((d) => d === 'block'), JSON.stringify(hints))
check('the page itself does not scroll sideways on a phone', await evaluate(`document.documentElement.scrollWidth <= window.innerWidth`))
await shot('fix-chips-phone')
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false })
await send('Page.reload')
await waitFor(`!!document.querySelector('fieldset')`, 'the filters')
const wide = await evaluate(`[...document.querySelectorAll('fieldset p')].map((p) => getComputedStyle(p).display)`)
check('the scroll hint is hidden on a laptop', wide.every((d) => d === 'none'), JSON.stringify(wide))

check('no inline style attributes', (await evaluate(`document.querySelectorAll('[style]').length`)) === 0)
check('no errors or warnings', errors.length === 0, JSON.stringify(errors))
socket.close()
const failed = results.filter((ok) => !ok).length
console.log(failed ? `${failed} check(s) failed` : `all ${results.length} checks passed`)
process.exit(failed ? 1 : 0)
"}

