}

.period {
  flex: none;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

/* Column widths hold 3, 5 or 8 thumbnails a row. */
.small {
  width: 11.5rem;
}

.medium {
  width: 19.5rem;
}

.large {
  width: 31.5rem;
}

/* Works fill rows from the axis upward, oldest at the bottom left. */
.stack {
  display: flex;
  flex-wrap: wrap-reverse;
  gap: var(--space-2);

