Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\design_check.mjs", "content": "// Checks the three design changes in the built app and takes pictures.
import { writeFileSync } from 'node:fs'
const PORT = 9343
const [, , outDir] = process.argv
const APP = 'http://localhost:4173/mp2/'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && ['error', 'warning'].includes(message.params.entry.level)) errors.push(message.params.entry.text + ' ' + (message.params.entry.url ?? ''))
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}
async function waitFor(check, label) {
  for (let attempt = 0; attempt < 80; attempt++) {
    if (await evaluate(check)) return
    await sleep(250)
  }
  throw new Error('Timed out waiting for ' + label)
}
const results = []
function check(label, ok, detail = '') {
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : '  -> ' + detail}`)
}
const shot = async (name) => writeFileSync(`${outDir}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'))
const laptop = () => send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false })
const phone = () => send('Emulation.setDeviceMetricsOverride', { width: 375, height: 800, deviceScaleFactor: 2, mobile: true })
// How far down the page the first artwork picture starts.
const firstPicture = () => evaluate(`Math.round(document.querySelector('main a[href*="/artwork/"] img, main a[href*="/artwork/"]').getBoundingClientRect().top)`)
const loaded = `[...document.querySelectorAll('main a[href*="/artwork/"] img')].slice(0, 6).every((img) => img.complete && img.naturalWidth > 0)`

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable')

// ---- Gallery
await laptop()
await send('Page.navigate', { url: APP + 'rooms' })
await waitFor(`!!document.querySelector('main a[href*="/artwork/"]')`, 'the gallery')
await waitFor(loaded, 'pictures')
check('the word "gallery" is on the page', await evaluate(`/gallery/i.test(document.body.innerText)`))
check('the navigation reads List, Gallery, Timeline', (await evaluate(`[...document.querySelectorAll('nav a')].map((a) => a.textContent).join(', ')`)) === 'List, Gallery, Timeline')
check('the browser tab is titled Gallery', (await evaluate(`document.title`)).startsWith('Gallery'))
const galleryTop = await firstPicture()
check(`artworks are visible without scrolling on a laptop (first picture at ${galleryTop}px of 900)`, galleryTop < 700, String(galleryTop))
check('12 department chips show, and no type chips', (await evaluate(`document.querySelectorAll('fieldset button[aria-pressed]').length`)) === 12)
await shot('design-gallery-laptop')
await evaluate(`[...document.querySelectorAll('button')].find((b) => /^Show all \\d+ types$/.test(b.textContent)).click()`)
await sleep(300)
check('opening the toggle shows the 24 types', (await evaluate(`document.querySelectorAll('fieldset button[aria-pressed]').length`)) === 36)
await evaluate(`[...document.querySelectorAll('button[aria-pressed]')].find((b) => b.textContent === 'Sculpture').click()`)
await evaluate(`[...document.querySelectorAll('button')].find((b) => b.textContent === 'Show fewer types').click()`)
await sleep(300)
check('a chosen type stays in view when the list is tucked away', (await evaluate(`[...document.querySelectorAll('fieldset:last-of-type button[aria-pressed]')].map((b) => b.textContent).join()`)) === 'Sculpture')
check('and the rooms are filtered by it', /artworks? match(es)? your filters/.test(await evaluate(`document.querySelector('main').innerText`)))
await shot('design-gallery-filtered')
await evaluate(`document.querySelector('main a[href*="/artwork/"]').click()`)
await waitFor(`!!document.querySelector('h1#artwork-title')`, 'the detail page')
check('the detail page links back to the gallery', /Back to the gallery/.test(await evaluate(`document.querySelector('article a').textContent`)))

// ---- Timeline
for (const [name, size, limit] of [['laptop', laptop, 450], ['phone', phone, 480]]) {
  await size()
  await send('Page.navigate', { url: APP + 'timeline' })
  await waitFor(`!!document.querySelector('main a[href*="/artwork/"]')`, 'the timeline')
  await waitFor(loaded, 'pictures')
  const top = await firstPicture()
  check(`timeline on a ${name}: the first artwork starts at ${top}px, with no gap above it`, top < limit, String(top))
  const tops = await evaluate(`[...document.querySelectorAll('main section')].map((s) => Math.round(s.getBoundingClientRect().top))`)
  check(`timeline on a ${name}: every period starts at the same height`, new Set(tops).size === 1, JSON.stringify(tops))
  check(`timeline on a ${name}: the page itself does not scroll sideways`, await evaluate(`document.documentElement.scrollWidth <= window.innerWidth`))
  await shot(`design-timeline-${name}`)
}
await phone()
await send('Page.navigate', { url: APP + 'rooms' })
await waitFor(`!!document.querySelector('main a[href*="/artwork/"]')`, 'the gallery')
await waitFor(loaded, 'pictures')
const phoneTop = await firstPicture()
check(`gallery on a phone: the first artwork starts at ${phoneTop}px of 800`, phoneTop < 800, String(phoneTop))
check('gallery on a phone: the page itself does not scroll sideways', await evaluate(`document.documentElement.scrollWidth <= window.innerWidth`))
await shot('design-gallery-phone')

check('no inline style attributes', (await evaluate(`document.querySelectorAll('[style]').length`)) === 0)
check('no errors or warnings', errors.length === 0, JSON.stringify(errors))
socket.close()
const failed = results.filter((ok) => !ok).length
console.log(failed ? `${failed} check(s) failed` : `all ${results.length} checks passed`)
process.exit(failed ? 1 : 0)
"}

