  padding: var(--space-4);
  color: var(--on-room);
  font-size: var(--text-sm);
  text-align: center;
}

/* Until it has arrived the picture takes up no room, so the message is not
   pushed aside by an empty box. */
.arriving {
  position: absolute;
  width: 1px;
  height: 1px;
