Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\image_check.mjs", "content": "// Checks in a real browser that detail pages show their pictures promptly.
import { writeFileSync } from 'node:fs'
const PORT = 9350
const [, , outDir] = process.argv
const APP = 'http://localhost:4173/mp2/'
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms))
async function target() {
  for (let attempt = 0; attempt < 40; attempt++) {
    try {
      const pages = await (await fetch(`http://127.0.0.1:${PORT}/json`)).json()
      const page = pages.find((p) => p.type === 'page')
      if (page) return page.webSocketDebuggerUrl
    } catch { /* starting */ }
    await sleep(250)
  }
  throw new Error('Chrome did not start')
}
const socket = new WebSocket(await target())
await new Promise((resolve) => socket.addEventListener('open', resolve))
let nextId = 1
const waiting = new Map()
const errors = []
socket.addEventListener('message', (event) => {
  const message = JSON.parse(event.data)
  if (message.method === 'Runtime.exceptionThrown') errors.push(message.params.exceptionDetails.exception?.description ?? message.params.exceptionDetails.text)
  if (message.method === 'Log.entryAdded' && ['error', 'warning'].includes(message.params.entry.level)) errors.push(message.params.entry.text + ' ' + (message.params.entry.url ?? ''))
  if (message.id && waiting.has(message.id)) { waiting.get(message.id)(message); waiting.delete(message.id) }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = nextId++
  waiting.set(id, resolve)
  socket.send(JSON.stringify({ id, method, params }))
})
const evaluate = async (expression) => {
  const reply = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true })
  if (reply.result.exceptionDetails) throw new Error(JSON.stringify(reply.result.exceptionDetails))
  return reply.result.result.value
}
async function waitFor(check, label, attempts = 120) {
  for (let attempt = 0; attempt < attempts; attempt++) {
    if (await evaluate(check)) return true
    await sleep(100)
  }
  console.log('Timed out waiting for ' + label)
  return false
}
const results = []
function check(label, ok, detail = '') {
  results.push(ok)
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${ok ? '' : '  -> ' + detail}`)
}
const shot = async (name) => writeFileSync(`${outDir}/${name}.png`, Buffer.from((await send('Page.captureScreenshot', { format: 'png' })).result.data, 'base64'))

// The large picture on a detail page, once it is really on show.
const PICTURE = `(() => {
  const img = document.querySelector('article figure img, article img')
  if (!img || !img.complete || img.naturalWidth === 0) return null
  const box = img.getBoundingClientRect()
  if (box.width < 50 || getComputedStyle(img).opacity === '0') return null
  return { src: img.currentSrc, width: Math.round(box.width), height: Math.round(box.height) }
})()`
const sizeOf = (src) => src.match(/\/full\/([^/]+)\//)?.[1]

await send('Runtime.enable'); await send('Log.enable'); await send('Page.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false })

async function visit(id, label, expectedSize) {
  const started = Date.now()
  await send('Page.navigate', { url: APP + 'artwork/' + id })
  const shown = await waitFor(`!!${PICTURE}`, 'the picture of ' + id, 300)
  const took = Date.now() - started
  const picture = shown ? await evaluate(PICTURE) : null
  check(`${label} (${id}): the picture is shown, after ${took} ms`, shown && took < 5000, String(took))
  check(`${label} (${id}): at the size ${expectedSize}`, picture && sizeOf(picture.src) === expectedSize, JSON.stringify(picture))
  check(`${label} (${id}): the loading message has gone`, !(await evaluate(`/Loading the picture/.test(document.body.innerText)`)))
  await shot('image-' + id)
}

await visit(61600, 'the reported work, a large original', '843,')
await visit(11144, 'a small original', '!843,843')
await visit(28560, 'a well known work', '843,')

// Step forward a few times: each picture should be on show when the step ends.
for (let step = 1; step <= 4; step++) {
  const before = await evaluate(`location.pathname`)
  await evaluate(`[...document.querySelectorAll('article a, article button')].find((el) => /^Next/.test(el.textContent.trim()) || /next/i.test(el.getAttribute('aria-label') ?? '')).click()`)
  await waitFor(`location.pathname !== ${JSON.stringify(before)}`, 'the next page')
  // Sampled part way through the transition, when the new picture is in view.
  await sleep(200)
  const during = await evaluate(`/Loading the picture/.test(document.body.innerText)`)
  await sleep(700)
  const picture = await evaluate(PICTURE)
  check(`step ${step} to ${await evaluate('location.pathname')}: the picture is shown`, !!picture, 'no picture')
  check(`step ${step}: no loading message during the transition`, !during)
}

check('no inline style attributes', (await evaluate(`document.querySelectorAll('[style]').length`)) === 0)
// A small original is expected to be refused once at the first size.
const unexpected = errors.filter((text) => !/403/.test(text))
const refusals = errors.length - unexpected.length
console.log(`refusals at the first size (expected for small originals): ${refusals}`)
check('no other errors or warnings', unexpected.length === 0, JSON.stringify(unexpected))
socket.close()
const failed = results.filter((ok) => !ok).length
console.log(failed ? `${failed} check(s) failed` : `all ${results.length} checks passed`)
process.exit(failed ? 1 : 0)
"}

