Write {"file_path": "C:\Users\User\AppData\Local\Temp\claude\C--Users-User-Dropbox-UIUC-2026-Fall-CS-409-Art-of-Web-Programming-mp2\2b80a059-753f-4620-b4b4-896dc263c6f9\scratchpad\scan_images.mjs", "content": "// Asks the museum for the large picture of every starter work, one at a time,
// and reports which are refused or slow at the size the app asks for first.
// Uses curl: the image server refuses Node's own fetch outright.
import { execFileSync } from 'node:child_process'
import { readFileSync, writeFileSync } from 'node:fs'

const [snapshotPath, outPath] = process.argv.slice(2)
const works = JSON.parse(readFileSync(snapshotPath, 'utf-8'))
const LIMIT_S = 30

function ask(imageId, size) {
  const url = `https://www.artic.edu/iiif/2/${imageId}/full/${size}/0/default.jpg`
  try {
    const out = execFileSync(
      'curl',
      ['-s', '-o', 'NUL', '--max-time', String(LIMIT_S), '-w', '%{http_code} %{time_total}', url],
      { encoding: 'utf-8' },
    )
    const [status, seconds] = out.trim().split(' ')
    return { status: Number(status), ms: Math.round(Number(seconds) * 1000) }
  } catch {
    return { status: 0, ms: LIMIT_S * 1000 }
  }
}

const rows = []
for (const work of works) {
  const first = ask(work.imageId, '843,')
  const row = { id: work.id, title: work.title.slice(0, 60), first }
  if (first.status !== 200) row.second = ask(work.imageId, '!843,843')
  rows.push(row)
  if (first.status !== 200 || first.ms > 2000) console.log(JSON.stringify(row))
  if (rows.length === 5 && rows.every((r) => r.first.status !== 200)) {
    console.log('The first five were all refused: the scan itself is being blocked. Stopping.')
    process.exit(2)
  }
}

const ok = rows.filter((row) => row.first.status === 200)
const slow = ok.filter((row) => row.first.ms > 2000)
const refused = rows.filter((row) => row.first.status !== 200)
const rescued = refused.filter((row) => row.second?.status === 200)
const times = ok.map((row) => row.first.ms).sort((a, b) => a - b)
const summary = {
  works: rows.length,
  firstSizeWorked: ok.length,
  firstSizeSlowOver2s: slow.length,
  firstSizeRefusedOrFailed: refused.length,
  ofThoseSecondSizeWorked: rescued.length,
  noLargePicture: refused.length - rescued.length,
  medianMs: times[Math.floor(times.length / 2)],
  slowestMs: times[times.length - 1],
  secondSizeTimesMs: rescued.map((row) => row.second.ms),
}
console.log('SUMMARY ' + JSON.stringify(summary, null, 1))
writeFileSync(outPath, JSON.stringify({ summary, rows }, null, 1), 'utf-8')
"}

